function calMonth(list){const c=S.cal,[st]=calRange(),t=todayK(),m=c.cursor.slice(0,7),by={};for(const x of list)(by[x.date]=by[x.date]||[]).push(x);const trips=calTrips();
 let h=`<div class="cal-grid month"><div class="cal-dow">${['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'].map(d=>`<span>${d}</span>`).join('')}</div><div class="cal-cells">`;
 for(let i=0;i<42;i++){const k=addD(st,i),xs=by[k]||[],tr=trips.filter(p=>p.start_date<=k&&p.end_date>=k);
  h+=`<div class="cal-cell ${k.slice(0,7)!==m?'out':''} ${k===t?'today':''} ${k===c.day?'picked':''}" data-action="cal-day" data-day="${k}" role="button" tabindex="0" aria-label="${k}"><b>${+k.slice(8)}</b>${tr.map(p=>`<span class="cal-trip c-${p.space==='work'?'work':'couple'} ${p.start_date===k?'start':''} ${p.end_date===k?'end':''}" title="${e(p.title)}">${p.start_date===k||k.endsWith('-01')||(dP(k).getUTCDay()===1)?`${I('plane',11)} ${e(p.destination||p.title)}`:'&nbsp;'}</span>`).join('')}${xs.slice(0,3).map(x=>calChip(x)).join('')}${xs.length>3?`<span class="cal-more">+${xs.length-3} más</span>`:''}<span class="cal-dots">${xs.slice(0,4).map(x=>`<i class="c-${calCls(x)}"></i>`).join('')}</span></div>`;}
 return h+'</div></div>';}
function calWeek(list){const [st]=calRange(),t=todayK();let h='<div class="cal-week">';for(let i=0;i<7;i++){const k=addD(st,i),xs=list.filter(x=>x.date===k),tr=calTrips().filter(p=>p.start_date<=k&&p.end_date>=k);h+=`<div class="cal-wday ${k===t?'today':''}"><button class="cal-wday-h" data-action="cal-day" data-day="${k}"><small>${new Date(k+'T12:00:00').toLocaleDateString('es-ES',{weekday:'short'})}</small><b>${+k.slice(8)}</b></button>${tr.map(p=>`<span class="cal-trip c-${p.space==='work'?'work':'couple'} start end">${I('plane',11)} ${e(p.destination||p.title)}</span>`).join('')}${xs.map(x=>calChip(x,true)).join('')||'<span class="cal-empty">—</span>'}</div>`;}return h+'</div>';}
function calAgenda(list){const days={};for(const x of list)(days[x.date]=days[x.date]||[]).push(x);const ks=Object.keys(days);return ks.length?`<div class="cal-agenda">${ks.map(k=>`<div class="cal-aday"><div class="cal-aday-h ${k===todayK()?'today':''}"><b>${+k.slice(8)}</b><small>${new Date(k+'T12:00:00').toLocaleDateString('es-ES',{weekday:'long',month:'short'})}</small></div><div class="cal-aday-list">${days[k].map(x=>`<div class="cal-arow">${calChip(x,true)}${calStateBadge(x)}</div>`).join('')}</div></div>`).join('')}</div>`:'<div class="full-empty">Nada en los próximos 60 días.</div>';}
