async function updateAfter(projectId){await loadDash();if(S.view==='dates'){try{await loadCal();}catch(ex){console.error('Calendario',ex);}}if(S.view==='actions')S.actionData=await api('/api/action-center');if(S.view==='activity')await loadActivity().catch(()=>{});if(S.view==='board')await loadBoard().catch(()=>{});if(S.view==='finance')await loadFin().catch(()=>{});if(S.view==='budgets'){S.budgetHist=await api('/api/budget/history').catch(()=>null);S.destNotes=(await api('/api/budget/notes').catch(()=>({items:[]}))).items;}if(S.view==='meetings'&&!S.meetingId)await loadMeetings().catch(()=>{});if(S.view==='couple')await loadCouple().catch(()=>{});if(S.view==='notices'){S.noticeData=await api('/api/notifications');S.pushStatus=await api('/api/push/status').catch(()=>null);}if(S.view==='trash')S.trashData=await api('/api/trash');if(S.view==='archives')S.archiveData=await api('/api/archives');if(S.view==='knowledge')S.knowledgeData=await api('/api/knowledge');if(S.view==='intelligence')S.analyticsData=await api('/api/analytics?space='+encodeURIComponent(S.analyticsSpace==='all'?'':S.analyticsSpace));if(S.view==='guardian'){S.guardianData=await api('/api/guardian/report');S.guardianInsights=await api('/api/guardian/insights');S.guardianActions=await api('/api/guardian/actions');}if(projectId&&S.view==='project'&&S.project?.id===projectId)await loadProject(projectId);render();}
async function resyncFromServer(){
 if(!S.me)return;
 // Never replace a form that one of the two people is editing.
 if(S.modal||document.activeElement?.matches('textarea,input,[contenteditable]')){S.pending=true;updateConnection();return;}
 try{await updateAfter(S.project?.id);S.pending=false;updateConnection();}
 catch(ex){if(ex.status===404){await loadDash();nav('home');}else{S.pending=true;updateConnection();console.error('Sincronización de recuperación',ex);}}
}
function conn(){
 // Cloudflare Durable Objects accept /api/ws. /api/stream deliberately returns 410.
 S.wsGeneration=(S.wsGeneration||0)+1;
 const generation=S.wsGeneration;
 clearTimeout(S.wsRetryTimer);
 try{S.stream?.close();}catch{}
 S.online=false;updateConnection();
 const protocol=location.protocol==='https:'?'wss:':'ws:';
 let ws;
 try{ws=new WebSocket(protocol+'//'+location.host+'/api/ws');}
 catch(ex){console.error('Conexión en tiempo real',ex);return;}
 S.stream=ws;
 ws.onopen=()=>{if(generation!==S.wsGeneration||!S.me)return;
  const reconnected=Boolean(S.wsHasConnected);S.wsHasConnected=true;
  S.wsFailures=0;S.online=true;updateConnection();
  // A disconnected PC can miss broadcasts: re-read authoritative SQLite after reconnect.
  if(reconnected)void resyncFromServer();
 };
 ws.onmessage=async ev=>{
  if(generation!==S.wsGeneration||!S.me||ev.data==='pong')return;
  let msg;try{msg=JSON.parse(ev.data);}catch{return;}
  if(msg.actor===S.me.id)return;
  if(S.modal||document.activeElement?.matches('textarea,input,[contenteditable]')){
    S.pending=true;updateConnection();toast('Hay cambios de la otra persona. Pulsa Actualizar.','info');return;
  }
  try{await updateAfter(S.project?.id);toast('Cambios compartidos actualizados.','info');}
  catch(ex){if(ex.status===404){await loadDash();nav('home');}else console.error('Sincronización',ex);}
 };
 ws.onclose=()=>{
  if(generation!==S.wsGeneration||!S.me)return;
  S.online=false;updateConnection();
  S.wsFailures=Math.min(5,(S.wsFailures||0)+1);
  const wait=Math.min(20000,1000*2**(S.wsFailures-1));
  clearTimeout(S.wsRetryTimer);S.wsRetryTimer=setTimeout(()=>{if(generation===S.wsGeneration&&S.me)conn();},wait);
 };
 ws.onerror=()=>{if(generation===S.wsGeneration){S.online=false;updateConnection();}};
}
function updateConnection(){const x=$('#live-status');if(x)x.innerHTML=`<span class="live-dot ${S.online?'':'offline'}"></span> ${S.pending?'Cambios nuevos · actualizar':S.online?'Sincronización activa':'Reconectando…'}`;}
function renderSetup(enabled){const app=$('#app');app.innerHTML=`<div class="login-screen"><div class="login-aside"><div class="brand large"><img class="dupla-icon" src="/dupla-icon.svg" alt="DUPLA"/><span>DUPLA</span></div><div class="login-story"><span class="eyebrow light">PRIMER ACCESO · PRIVADO</span><h1>Dos personas.<br/>Un mismo<br/><i>espacio.</i></h1><p>Configurad vuestras dos cuentas una sola vez. Todo lo que creéis será compartido.</p></div><div class="login-footer">Álvaro & Angie · Acceso privado</div></div><main class="login-main"><div class="login-box"><span class="eyebrow">ACTIVACIÓN DE VUESTRO ESPACIO</span><h2>Vamos a empezar juntos.</h2>${enabled?`<p>Introduce la clave secreta definida en el alojamiento y las credenciales de los dos. Este formulario solo está disponible antes de crear las cuentas.</p><form id="setup-form" class="stack-form"><label>Clave de instalación<input type="password" name="setup_token" required minlength="32" autocomplete="off" placeholder="Clave privada de activación"/><button type="button" class="dupla-reveal" data-action="password-toggle" aria-pressed="false">Mostrar</button></label><label>Correo de Álvaro<input type="email" name="email_a" required autocomplete="off"/></label><label>Contraseña de Álvaro (mínimo 12 caracteres)<input type="password" name="password_a" required minlength="12" autocomplete="new-password"/><button type="button" class="dupla-reveal" data-action="password-toggle" aria-pressed="false">Mostrar</button></label><label>Correo de Angie<input type="email" name="email_b" required autocomplete="off"/></label><label>Contraseña de Angie (mínimo 12 caracteres)<input type="password" name="password_b" required minlength="12" autocomplete="new-password"/><button type="button" class="dupla-reveal" data-action="password-toggle" aria-pressed="false">Mostrar</button></label><button class="btn primary full" type="submit">Crear nuestras dos cuentas ${I('arrow',18)}</button><p class="form-error" id="setup-error" role="alert"></p></form>`:`<p>El servidor todavía no tiene cuentas. Para permitir la activación web, configura el secreto <strong>SETUP_TOKEN</strong> en Cloudflare Workers y vuelve a abrir esta página.</p><button class="btn outline" onclick="location.reload()">Comprobar configuración</button>`}<div class="private-note">${I('users',16)} No compartáis las claves en ChatGPT. Guardadlas en vuestro gestor de contraseñas.</div></div></main></div>`;
const form=$('#setup-form');if(form)form.addEventListener('submit',async ev=>{ev.preventDefault();const data=Object.fromEntries(new FormData(form));const btn=form.querySelector('button');btn.disabled=true;btn.textContent='Creando cuentas…';try{await api('/api/initialize','POST',data);renderLogin();toast('¡Cuentas creadas! Inicia sesión.','info');}catch(ex){$('#setup-error').textContent=ex.message;}finally{btn.disabled=false;btn.innerHTML='Crear nuestras dos cuentas '+I('arrow',18);}});
}
const pkB=s=>Uint8Array.from(atob(s.replace(/-/g,'+').replace(/_/g,'/')+'==='.slice((s.length+3)%4)),c=>c.charCodeAt(0)),pkS=b=>btoa(String.fromCharCode(...new Uint8Array(b))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
async function passkeyLogin(){const o=await api('/api/passkeys/login/options','POST',{}),c=await navigator.credentials.get({publicKey:{challenge:pkB(o.challenge),rpId:o.rpId,userVerification:'required',timeout:o.timeout}});
 return api('/api/passkeys/login','POST',{id:c.id,response:{clientDataJSON:pkS(c.response.clientDataJSON),authenticatorData:pkS(c.response.authenticatorData),signature:pkS(c.response.signature)}});}
async function passkeyRegister(){const o=await api('/api/passkeys/register/options','POST',{}),c=await navigator.credentials.create({publicKey:{...o,challenge:pkB(o.challenge),user:{...o.user,id:pkB(o.user.id)},excludeCredentials:o.excludeCredentials.map(x=>({...x,id:pkB(x.id)}))}});
 await api('/api/passkeys/register','POST',{id:c.id,response:{clientDataJSON:pkS(c.response.clientDataJSON),attestationObject:pkS(c.response.attestationObject)}});}
function renderLogin(){const app=$('#app');app.innerHTML=`<div class="login-screen"><div class="login-aside"><div class="brand large"><img class="dupla-icon" src="/dupla-icon.svg" alt="DUPLA"/><span>DUPLA</span></div><div class="login-story"><span class="eyebrow light">UN LUGAR. DOS PERSONAS.</span><h1>Nuestras ideas<br/>merecen un<br/><i>lugar propio.</i></h1><p>El espacio privado donde trabajo y vida en común encuentran su sitio.</p><div class="login-chips"><span>${I('briefcase',16)} Lo que construimos</span><span>${I('heart',16)} Lo que vivimos</span></div></div><div class="login-footer">Hecho exclusivamente para vosotros dos ✦</div></div><main class="login-main"><div class="login-box"><span class="eyebrow">BIENVENIDOS A VUESTRO ESPACIO</span><h2>Qué bien tenerte aquí.</h2><p>Inicia sesión para volver a todo lo que estáis construyendo juntos.</p><form id="login-form" class="stack-form"><label>Correo electrónico<input type="email" name="email" required autocomplete="email" placeholder="tu@correo.com" /></label><label>Contraseña<input type="password" name="password" required autocomplete="current-password" placeholder="Tu contraseña" /><button type="button" class="dupla-reveal" data-action="password-toggle" aria-pressed="false">Mostrar</button></label><button class="btn primary full" type="submit">Entrar en nuestro espacio ${I('arrow',18)}</button>${window.PublicKeyCredential?`<div class="pk-or"><span>o</span></div><button type="button" class="btn outline full pk-login" id="pk-login">${I('lock',17)} Entrar con Face ID o huella</button>`:''}<p id="login-error" class="form-error"></p></form><div class="private-note">${I('users',16)} Acceso exclusivamente para Álvaro y Angie. Sin registro público.</div></div></main></div>`;$('#pk-login')?.addEventListener('click',async ev=>{const b=ev.currentTarget,er=$('#login-error');b.disabled=true;er.textContent='';try{const r=await passkeyLogin();S.me=r.user;await loadDash();setTimeout(pushAsk,2500);render();}catch(ex){if(!S.me){renderLogin();$('#login-error').textContent=ex.name==='NotAllowedError'?'Cancelado. Si aún no la has activado, entra con contraseña y ve a Ajustes › Dispositivos.':ex.message;}}});$('#login-form').addEventListener('submit',async ev=>{ev.preventDefault();const f=new FormData(ev.target);const b=ev.target.querySelector('button');b.disabled=true;b.textContent='Entrando…';try{const r=await api('/api/login','POST',{email:f.get('email'),password:f.get('password')});S.me=r.user;await loadDash();setTimeout(pushAsk,2500);if(new URLSearchParams(location.search).has('drive')){S.view='settings';S.settingsTab='datos';history.replaceState(null,'',location.pathname);S.driveSt=await api('/api/backups/drive').catch(()=>null);setTimeout(()=>toast('Google Drive conectado: la primera copia se hará en la próxima hora (o pulsa «Hacer copia ahora»).'),600);}else if(new URLSearchParams(location.search).get('google')==='personal'){S.view='dates';history.replaceState(null,'',location.pathname);setTimeout(()=>toast('Calendarios conectados: elige cuáles se fusionan.'),600);}else if(new URLSearchParams(location.search).has('google')||new URLSearchParams(location.search).has('design')){S.googleStatus=await api('/api/google/status');S.designStatus=Object.fromEntries(await Promise.all(['figma','canva'].map(async p=>[p,await api('/api/design/'+p+'/status')])));S.view='connections';history.replaceState(null,'',location.pathname);}conn();render();}catch(ex){$('#login-error').textContent=ex.message;}finally{b.disabled=false;b.innerHTML='Entrar en nuestro espacio '+I('arrow',18);}});}
function navBtn(view,icon,label,count){const active=S.view===view||(S.view==='project'&&S.project?.space===view);return `<button class="nav-item ${active?'active':''}" data-nav="${view}"${active?' aria-current="page"':''}>${I(icon)} <span>${label}</span>${count?`<small>${count}</small>`:''}</button>`;}
function sidebar(){const ps=(S.dash?.projects||[]).filter(p=>!p.archived),ideas=S.dash?.ideas?.filter(i=>i.state!=='converted').length||0;return `<aside class="sidebar" id="sidebar"><div class="sidebar-inner"><div class="brand"><img class="dupla-icon" src="/dupla-icon.svg" alt="DUPLA"/><div class="brand-text">DUPLA <small>Nuestro espacio, todos nuestros planes</small></div></div><nav class="side-group" aria-label="Navegación principal">${navBtn('home','home','Inicio')}${navBtn('work','briefcase','Trabajo',ps.filter(p=>p.space==='work').length)}${navBtn('couple','heart','Nuestro espacio',ps.filter(p=>p.space==='couple').length)}${navBtn('dates','calendar','Calendario')}${navBtn('ideas','spark','Ideas',ideas)}${navBtn('guardian','layers','Director General')}${navBtn('activity','activity','Actividad')}${navBtn('meetings','video','Reuniones')}${navBtn('board','checkcircle','Tareas',(S.dash?.board_open||'')||undefined)}${navBtn('finance','chart','Finanzas')}${navBtn('budgets','wallet','Presupuestos')}${navBtn('dupla','bot','Chat con Dupla')}${navBtn('connections','link','Conexiones')}${navBtn('settings','settings','Ajustes')}<div class="side-label second">MÁS HERRAMIENTAS</div>${navBtn('actions','checkcircle','Centro de acciones')}${navBtn('search','search','Buscar en todo')}${navBtn('notices','bell','Notificaciones',S.dash?.unread||0)}${navBtn('knowledge','file','Biblioteca')}${navBtn('intelligence','activity','Datos e inteligencia')}</nav><div class="side-bottom"><div class="profile"><span class="avatar avatar-profile">${e(initials(S.me.name))}</span><div><b>${e(S.me.name)}</b><small>Sesión iniciada</small></div><button class="icon-btn profile-out" data-action="logout" title="Cerrar sesión" aria-label="Cerrar sesión">${I('logout',17)}</button></div></div></div></aside>`;}
function header(){const title=S.view==='home'?'Inicio':S.view==='project'?(S.project?.space==='work'?'Trabajo':'Nuestro espacio'):{work:'Trabajo',couple:'Nuestro espacio',ideas:'Ideas',search:'Buscar en todo',notices:'Notificaciones',trash:'Papelera',archives:'Archivados',dates:'Calendario',activity:'Actividad',connections:'Conexiones',knowledge:'Biblioteca',intelligence:'Datos e inteligencia',guardian:'Director General',settings:'Ajustes',actions:'Centro de acciones',dupla:'Chat con Dupla'}[S.view];const unread=S.dash?.unread||0,users=S.dash?.users||[];const tab=(v,l,i)=>{const on=S.view===v||(S.view==='project'&&S.project?.space===v);return `<button class="top-tab ${on?'active':''}" data-nav="${v}"${on?' aria-current="page"':''}>${I(i,16)} ${l}</button>`;};return `<header class="topbar"><div class="topbar-left"><button class="icon-btn mobile-menu" data-action="toggle-menu" aria-controls="sidebar" aria-expanded="false" aria-label="Abrir menú">${I('menu',21)}</button><b class="topbar-title">${e(title||'')}</b><nav class="top-tabs" aria-label="Accesos rápidos">${tab('home','Inicio','home')}${tab('work','Trabajo','briefcase')}${tab('couple','Nuestro espacio','heart')}${tab('dates','Calendario','calendar')}${tab('activity','Actividad','activity')}</nav></div><div class="topbar-right"><form id="quick-search" class="quick-search" role="search"><span class="qs-icon">${I('search',16)}</span><input name="q" type="search" placeholder="Buscar en todo…" aria-label="Buscar en todo" value="${e(S.lastQuery||'')}" autocomplete="off" maxlength="120"/><kbd>Ctrl K</kbd></form><button class="icon-btn top-search-btn" data-nav="search" aria-label="Buscar en todo">${I('search',19)}</button><button id="live-status" class="live-status" data-action="sync"><span class="live-dot offline"></span> Conectando…</button><button class="icon-btn top-bell" data-nav="notices" aria-label="Notificaciones: ${unread} sin leer">${I('bell',19)}${unread?`<span class="badge">${unread>99?'99+':unread}</span>`:''}</button><div class="couple-chip"><div class="top-avatars">${users.map((u,i)=>avatar(u.name,i===0?'av-first':'av-second')).join('')}</div><div class="couple-names"><b>${e(users.map(u=>u.name.split(' ')[0]).join(' y ')||S.me.name)}</b><small>${S.shared?.couple_since?'Juntos desde '+new Date(S.shared.couple_since+'T12:00:00').getFullYear():'Vuestro espacio compartido'}</small></div></div></div></header>`;}
function render(){if(!S.me)return renderLogin();if(MT?.local)queueMicrotask(mtAttach);applyTheme();$('#app').innerHTML=`<div class="shell">${sidebar()}<div class="workspace">${header()}<main class="content" id="content">${content()}</main><footer class="site-footer">DUPLA <span>✦</span> Álvaro & Angie · Lo nuestro, a nuestra manera.</footer></div></div><div id="modal-root">${S.modal?modalHTML():''}</div>`;updateConnection();bindGlobal();if(S.modal)loadTaskNotes();}
function content(){switch(S.view){case 'actions':return actionCenterPage();case 'work':return spacePage('work');case 'couple':return spacePage('couple');case 'project':return projectPage();case 'ideas':return ideasPage();case 'search':return searchPage();case 'notices':return notificationsPage();case 'knowledge':return knowledgePage();case 'intelligence':return intelligencePage();case 'guardian':return guardianPage();case 'trash':return trashPage();case 'archives':return archivesPage();case 'dates':return datesPage();case 'activity':return activityPage();case 'meetings':return S.meetingId?meetingRoom():meetingsPage();case 'board':return boardPage();case 'budgets':return budgetsPage();case 'finance':return financePage();case 'connections':return connectionsPage();case 'settings':return settingsPage();case 'dupla':return duplaPage();default:return homePage();}}
// DUPLA_ACTION_CENTER_V46 - Pantalla de tareas con operaciones reales de guardado.
function actionCenterPage(){
 const tasks=S.actionData?.items||[],now=new Date().toISOString().slice(0,10),next=new Date(Date.now()+7*86400000).toISOString().slice(0,10);
 const notDone=tasks.filter(t=>t.state!=='done'),due=notDone.filter(t=>t.due_date&&t.due_date<now),soon=notDone.filter(t=>t.due_date&&t.due_date>=now&&t.due_date<=next);
 const filtered=tasks.filter(t=>S.actionFilter==='all'||(S.actionFilter==='open'&&t.state!=='done')||(S.actionFilter==='overdue'&&t.state!=='done'&&t.due_date&&t.due_date<now)||(S.actionFilter==='week'&&t.state!=='done'&&t.due_date&&t.due_date>=now&&t.due_date<=next)||(S.actionFilter==='mine'&&t.state!=='done'&&t.assigned_to===S.me?.id));
 return `<div class="page"><div class="page-heading"><span class="eyebrow">QUE PASA AHORA</span><h1>Centro de acciones<span class="title-dot">.</span></h1><p>Tareas reales de todos vuestros proyectos. Cada cambio se guarda para los dos.</p></div><div class="action-metrics"><div class="action-metric"><small>Pendientes</small><b>${notDone.length}</b></div><div class="action-metric"><small>Vencidas</small><b>${due.length}</b></div><div class="action-metric"><small>Próximos 7 días</small><b>${soon.length}</b></div><div class="action-metric"><small>Terminadas</small><b>${tasks.length-notDone.length}</b></div></div><div class="action-filters" aria-label="Filtrar tareas">${[['open','Pendientes'],['mine','Asignadas a mí'],['overdue','Vencidas'],['week','Próximos 7 días'],['all','Todas']].map(([v,label])=>`<button class="action-filter ${S.actionFilter===v?'selected':''}" data-action="actions-filter" data-filter="${v}" aria-pressed="${S.actionFilter===v}">${label}</button>`).join('')}</div><section class="panel action-list">${filtered.length?filtered.map(t=>`<div class="action-entry"><button class="action-check ${t.state==='done'?'complete':''}" data-action="action-toggle" data-id="${t.id}" aria-label="${t.state==='done'?'Reabrir':'Completar'} tarea ${e(t.title)}" title="${t.state==='done'?'Reabrir tarea':'Marcar completada'}">${I('check',15)}</button><div class="action-info"><b class="${t.state==='done'?'is-done':''}">${e(t.title)}</b><p>${e(t.project_title)} · ${t.space==='work'?'Trabajo':'Nuestro espacio'} ${t.assignee_name?'· '+e(t.assignee_name):''}</p><div class="action-meta">${t.priority==='high'?'<span class="action-tag high">Prioridad alta</span>':''}${t.due_date?`<span class="action-tag ${t.due_date<now&&t.state!=='done'?'late':''}">${t.due_date<now&&t.state!=='done'?'Vencida · ':''}${fmt(t.due_date)}</span>`:'<span class="action-tag">Sin fecha</span>'}</div></div><button class="btn outline" data-action="action-edit" data-id="${t.id}">Editar ${I('edit',14)}</button><button class="btn outline" data-project="${t.project_id}">Abrir ${I('arrow',14)}</button></div>`).join(''):'<div class="empty-mini">No hay tareas con este filtro. Puedes crear una tarea dentro de cualquier proyecto.</div>'}</section><p class="action-hint">Las tareas nuevas se crean en Trabajo o Nuestro espacio. Un cambio realizado aquí también se refleja en su proyecto y en la actividad compartida.</p></div>`;
}

function kpi(icon,title,n,tag){return `<div class="kpi"><span class="kpi-icon">${I(icon,20)}</span><div><span>${e(title)}</span><b>${n}</b></div><small>${e(tag)}</small></div>`;}
function hello(){const h=new Date().getHours();return h<13?'Buenos días':h<20?'Buenas tardes':'Buenas noches';}
// ---- DUPLA 6 · Inicio fusionado (imagen + datos reales) y agente Dupla ----
const today=()=>new Date().toISOString().slice(0,10);
const plural=(n,one,many)=>`${n} ${n===1?one:many}`;
const dayDiff=(a,b)=>Math.round((new Date(a+'T12:00:00')-new Date(b+'T12:00:00'))/864e5);
const since=d=>{const s=(Date.now()-new Date(d))/1000;return s<60?'Ahora mismo':s<3600?`Hace ${Math.floor(s/60)} min`:s<86400?`Hace ${Math.floor(s/3600)} h`:s<172800?'Ayer':short(d);};
const rangeText=(a,b)=>{if(!a)return '';const A=new Date(a+'T12:00:00'),B=b?new Date(b+'T12:00:00'):null;const m=x=>x.toLocaleDateString('es-ES',{month:'short'}).replace('.','');return B&&b!==a?(A.getMonth()===B.getMonth()&&A.getFullYear()===B.getFullYear()?`${A.getDate()} – ${B.getDate()} ${m(B)} ${B.getFullYear()}`:`${A.getDate()} ${m(A)} – ${B.getDate()} ${m(B)} ${B.getFullYear()}`):`${A.getDate()} ${m(A)} ${A.getFullYear()}`;};
const KIND_ICON={trip:'plane',weekend:'plane',dinner:'heart',celebration:'gift',shared:'heart',website:'globe',campaign:'spark',app:'layers',automation:'refresh',ai_agent:'bot',freelance:'briefcase',blank:'folder'};
const isTrip=p=>['trip','weekend'].includes(p.kind)||Boolean(p.destination);
const coverUrl=p=>p.cover_file?`/api/projects/${p.id}/cover?v=${encodeURIComponent(p.cover_file.slice(0,8))}`:'';
const coupleNames=()=>{const others=(S.dash?.users||[]).filter(u=>u.id!==S.me.id).map(u=>u.name.split(' ')[0]);return [S.me.name.split(' ')[0],...others].join(' y ');};
// Próximo viaje: en curso primero, si no el siguiente con fecha. Nunca uno ya terminado.
function nextTrip(){const t=today();return (S.dash?.projects||[]).filter(p=>!p.archived&&p.space==='couple'&&isTrip(p)&&p.start_date&&(p.end_date||p.start_date)>=t).sort((a,b)=>a.start_date.localeCompare(b.start_date))[0]||null;}
function tripStatus(p){const t=today();if(p.start_date>t){const n=dayDiff(p.start_date,t);return {label:'Faltan',value:n,unit:n===1?'día':'días'};}const total=dayDiff(p.end_date||p.start_date,p.start_date)+1,day=dayDiff(t,p.start_date)+1;return {label:'En marcha',value:`Día ${day}`,unit:`de ${total}`};}
async function loadWeather(){const p=nextTrip();if(!p?.destination)return;const key=p.destination.toLowerCase();S.weather=S.weather||{};if(S.weather[key])return;S.weather[key]={loading:true};
 try{S.weather[key]=(await api('/api/weather?q='+encodeURIComponent(p.destination))).weather||{found:false};}catch{S.weather[key]={found:false};}
 if(S.view==='home'&&!S.modal&&!document.activeElement?.matches('input,textarea,select'))render();}
function weatherHtml(p){const w=S.weather?.[p.destination.toLowerCase()];if(!w||w.loading||!w.found)return '';return `<div class="h6-weather" title="${e(w.text)} ahora en ${e(w.place)}">${I(w.code<=1&&w.day?'sun':w.day?'sun':'moon',22)}<b>${w.temp}°C</b><small>${e(w.text)}</small></div>`;}
function summaryChips(){const want=S.shared?.home_summary||S.prefs?.home_summary||['trip','date','task','idea'],t=today(),out=[];const ps=S.dash.projects.filter(p=>!p.archived);
 if(want.includes('trip')){const p=nextTrip();out.push(p?`<button class="h6-chip" data-project="${p.id}">${I('plane',15)}<span><small>Próximo viaje</small><b>${e(p.destination||p.title)}</b></span></button>`:`<button class="h6-chip muted" data-action="new-trip">${I('plane',15)}<span><small>Próximo viaje</small><b>Sin planear</b></span></button>`);}
 if(want.includes('date')){const d=(S.dash.upcoming||[]).find(x=>x.kind==='event'&&x.date>=t&&x.space==='couple')||(S.dash.upcoming||[]).find(x=>x.kind==='event'&&x.date>=t);out.push(d?`<button class="h6-chip" data-project="${d.project_id}">${I('calendar',15)}<span><small>Próxima cita</small><b>${e(d.title)} · ${short(d.date)}</b></span></button>`:`<button class="h6-chip muted" data-action="quick-event">${I('calendar',15)}<span><small>Próxima cita</small><b>Nada a la vista</b></span></button>`);}
 if(want.includes('task')){const k=(S.dash.upcoming||[]).filter(x=>x.kind==='task'&&x.state!=='done').sort((a,b)=>a.date.localeCompare(b.date))[0];out.push(k?`<button class="h6-chip ${k.date<t?'late':''}" data-project="${k.project_id}">${I('checkcircle',15)}<span><small>${k.date<t?'Tarea atrasada':'Tarea importante'}</small><b>${e(k.title)} · ${short(k.date)}</b></span></button>`:`<span class="h6-chip muted">${I('checkcircle',15)}<span><small>Tareas</small><b>Todo al día</b></span></span>`);}
 if(want.includes('idea')){const i=(S.dash.ideas||[]).find(x=>x.state!=='converted');out.push(i?`<button class="h6-chip" data-nav="ideas">${I('spark',15)}<span><small>Idea reciente</small><b>${e(i.title)}</b></span></button>`:`<button class="h6-chip muted" data-action="new-idea">${I('spark',15)}<span><small>Idea reciente</small><b>Ninguna todavía</b></span></button>`);}
 return out.length?`<div class="h6-chips">${out.join('')}<button class="h6-chip-edit" data-action="home-summary" aria-label="Personalizar resumen">${I('settings',15)}</button></div>`:`<div class="h6-chips"><button class="h6-chip-edit" data-action="home-summary">${I('settings',15)} Personalizar resumen</button></div>`;}
function heroHtml(){const trip=nextTrip(),img=trip?coverUrl(trip):'';const st=trip?tripStatus(trip):null;
 return `<section class="h6-hero ${img?'has-photo':''}">${img?`<img class="h6-hero-img" src="${img}" alt="${e(trip.destination||trip.title)}"/>`:''}<div class="h6-hero-shade"></div><div class="h6-hero-body"><div class="h6-hero-text"><h1>Hola, ${e(coupleNames())}</h1><p>Grandes planes se construyen con pequeños momentos <span class="h6-heart">♥</span></p>${summaryChips()}</div>
 ${trip?`<div class="h6-trip-card"><div class="h6-trip-top"><div><b>${e(trip.destination||trip.title)}</b><small>${e(rangeText(trip.start_date,trip.end_date))}</small></div>${weatherHtml(trip)}</div><div class="h6-trip-bottom"><div><small>${st.label}</small><strong>${st.value}</strong> <span>${st.unit}</span></div><button class="h6-link" data-project="${trip.id}">Ver itinerario ${I('arrow',15)}</button></div></div>`
 :`<div class="h6-trip-card empty"><b>¿Cuál será vuestro próximo viaje?</b><small>Ponéis el destino y DUPLA trae la foto, el tiempo y la cuenta atrás.</small><button class="btn primary" data-action="new-trip">${I('plane',16)} Planificar viaje</button></div>`}</div>${trip?.cover_credit?`<small class="h6-credit">Foto: ${e(trip.cover_credit)}</small>`:''}</section>`;}
function quickActions(){const qa=[['new-project','folder','Crear proyecto','Trabajo o personal','blue'],['new-trip','plane','Planificar viaje','Destino, fechas y foto','sky'],['quick-event','calendar','Añadir evento','A un proyecto o plan','orange'],['new-idea','spark','Nueva idea','Guardado rápido','amber'],['quick-upload','upload','Subir archivo','Fotos, PDFs, etc.','indigo'],['ask-dupla','bot','Pedir a Dupla','Vuestro agente','violet']];
 return `<div class="h6-quick">${qa.map(([a,i,t,s,c])=>`<button class="h6-qa" data-action="${a}"><span class="h6-qa-icon ${c}">${I(i,20)}</span><span><b>${t}</b><small>${s}</small></span></button>`).join('')}</div>`;}
const showSpace=s=>pref(s==='work'?'home_show_work':'home_show_couple');
function plansHtml(){const t=today(),ps=S.dash.projects.filter(p=>!p.archived&&showSpace(p.space));
 const dated=ps.filter(p=>p.start_date&&(p.end_date||p.start_date)>=t).sort((a,b)=>a.start_date.localeCompare(b.start_date)).map(p=>({p,date:p.start_date,sub:`${p.end_date?dayDiff(p.end_date,p.start_date)+1+' días · ':''}${p.space==='work'?'Trabajo':'Nuestro espacio'}`}));
 const used=new Set(dated.map(x=>x.p.id));const events=(S.dash.upcoming||[]).filter(x=>x.kind==='event'&&x.date>=t&&!used.has(x.project_id)&&showSpace(x.space)).map(x=>({p:ps.find(p=>p.id===x.project_id)||{id:x.project_id,kind:'blank',space:x.space,title:x.project_title,tasks_total:0,tasks_done:0},date:x.date,title:x.title,sub:`${x.project_title} · ${x.space==='work'?'Trabajo':'Nuestro espacio'}`}));
 const gc=showSpace('couple')?(S.homeShared||[]).filter(x=>x.date>=t).map(x=>({p:{id:'',kind:'blank',space:'couple',title:x.title,tasks_total:0,tasks_done:0},date:x.date,title:x.title,g:true,sub:'Calendario compartido'+(x.time?' · '+x.time:'')})):[];
 const rows=[...dated,...events,...gc].sort((a,b)=>a.date.localeCompare(b.date)).slice(0,5);
 return rows.length?rows.map(({p,date,sub,title,g})=>{const d=new Date(date+'T12:00:00'),pc=pct(p.tasks_done,p.tasks_total);return `<button class="h6-plan" ${g?'data-nav="dates"':`data-project="${p.id}"`}><span class="h6-plan-date"><b>${capitalize(d.toLocaleDateString('es-ES',{weekday:'short'}).replace('.',''))}</b><small>${d.getDate()} ${d.toLocaleDateString('es-ES',{month:'short'}).replace('.','')}</small></span><span class="h6-plan-icon ${p.space}">${I(KIND_ICON[p.kind]||'folder',18)}</span><span class="h6-plan-main"><b>${e(title||p.title)}</b><small>${e(sub)}</small></span><span class="h6-plan-progress" title="${p.tasks_done}/${p.tasks_total} tareas"><i style="width:${pc}%"></i><small>${p.tasks_total?pc+'%':'—'}</small></span></button>`;}).join(''):`<div class="empty-mini">${I('calendar',26)}<p>Sin planes con fecha. Añadid fechas a un viaje o un evento a un proyecto.</p><button class="btn outline" data-action="quick-event">${I('plus',15)} Añadir evento</button></div>`;}
function activityHtml(items){return items?.length?items.map(a=>`<button class="h6-act" data-project="${a.project_id||''}"${a.project_id?'':' data-nav="activity"'}><span class="avatar ${a.user_id===S.me.id?'av-first':'av-second'}">${e(initials(a.author||'?'))}</span><span class="h6-act-main"><span><b class="h6-who">${e(a.author||'Alguien')}</b> ${e(a.action)}${a.detail?` <q>${e(a.detail)}</q>`:''}</span><small>${e(a.project_title||(a.space==='work'?'Trabajo':'Nuestro espacio'))}</small></span><time datetime="${e(a.created_at)}">${since(a.created_at)}</time></button>`).join(''):'<div class="empty-mini">Aún no hay actividad. Vuestra primera idea está esperando.</div>';}
function ideaBox(){const pending=(S.dash.ideas||[]).filter(i=>i.state!=='converted');const last=pending[0];
 return `<section class="panel h6-idea"><div class="panel-title"><h3>${I('spark',18)} ¿Una idea que no queréis olvidar?</h3><button class="text-btn" data-nav="ideas">Buzón (${pending.length}) ${I('arrow',15)}</button></div><form id="quick-idea-form" class="h6-idea-form"><input name="title" maxlength="160" required placeholder="Escribidla tal cual os viene…" autocomplete="off"/><select name="space" aria-label="Espacio"><option value="couple">Nuestro espacio</option><option value="work">Trabajo</option></select><button class="btn primary" type="submit">${I('plus',16)} Guardar</button></form>${last?`<button class="h6-resume" data-nav="ideas">${I('undo',16)}<span><small>Retomar idea pendiente</small><b>${e(last.title)}</b></span><time>${since(last.updated_at||last.created_at)}</time></button>`:''}</section>`;}
function duplaAvatar(size=''){const src=S.shared?.dupla_avatar_v?`/api/agent/avatar?v=${S.shared.dupla_avatar_v}`:'/dupla-avatar.jpg?v=1';return `<img class="dupla-ava ${size}" src="${src}" alt="Dupla"/>`;}
const DUPLA_LOGO=`<svg class="dupla-logo" viewBox="0 0 32 32" aria-hidden="true"><defs><linearGradient id="dlg" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#7d76de"/><stop offset="1" stop-color="#5b51b8"/></linearGradient></defs><circle cx="16" cy="16" r="16" fill="url(#dlg)"/><path d="M11.6 10.2c-2.2 0-3.8 1.7-3.8 3.8 0 3.6 4.4 6.4 6.6 7.9 1-.7 2.4-1.6 3.6-2.8-1.9-1.4-4.6-3.4-4.6-6.1 0-.9.3-1.8.8-2.4-.7-.3-1.6-.4-2.6-.4z" fill="#fff" opacity=".85"/><path d="M20.2 11.2c-1.3 0-2.4.7-3 1.7-.6-1-1.7-1.7-3-1.7-1.9 0-3.4 1.6-3.4 3.5 0 3.3 4 5.8 6.4 7.4 2.4-1.6 6.4-4.1 6.4-7.4 0-1.9-1.5-3.5-3.4-3.5z" fill="#fff"/></svg>`;
const DUPLA_SUGGESTIONS=['Planificar un viaje a…','Ideas para una cita','Crear itinerario con IA','Recordar aniversario','¿Qué tenemos pendiente esta semana?','Revisa qué se está retrasando'];
function duplaCard(){return `<section class="panel h6-dupla"><div class="h6-dupla-head">${duplaAvatar('lg')}<div><b>Dupla</b><small>Vuestro agente personal</small></div></div><p>Hola, ${e(S.me.name.split(' ')[0])}. Puedo planificar viajes por días, crear tareas y planes, organizar presupuestos o buscar cualquier cosa. <b>Siempre te enseño lo que voy a hacer antes de guardarlo.</b></p><div class="h6-sugs">${DUPLA_SUGGESTIONS.map(s=>`<button class="h6-sug" data-action="ask-dupla" data-prompt="${e(s)}">${e(s)}</button>`).join('')}</div><form class="h6-dupla-form" data-dupla-form="home"><input name="message" maxlength="2000" placeholder="Escribe a Dupla…" autocomplete="off" required/><button class="icon-btn" type="submit" aria-label="Enviar a Dupla">${I('arrow',18)}</button></form></section>`;}
function statusStrip(){const unread=S.dash.unread||0,push=S.pushStatus?.subscribed,ai=true;const g=S.googleStatus;return `<div class="h6-status"><button class="h6-stat" data-nav="notices">${I('bell',17)}<span><b>${unread} sin leer</b><small>${push?'Avisos en el móvil activos':'Avisos en el móvil: por activar'}</small></span></button><button class="h6-stat" data-nav="connections">${I('link',17)}<span><b>Conexiones</b><small>${g?.connected?'Google Calendar conectado':'Google Calendar: pendiente'}</small></span></button><button class="h6-stat" data-nav="dupla">${I('bot',17)}<span><b>Dupla</b><small>${ai?'Agente disponible':'Sin IA'}</small></span></button></div>`;}
function weeklyCard(){if(S.weekly===undefined){S.weekly=null;api('/api/weekly-review').then(r=>{S.weekly=r.review||false;if(S.view==='home'&&S.weekly)render();}).catch(()=>{S.weekly=false;});return '';}
 const w=S.weekly;let seen='';try{seen=localStorage.getItem('dupla-repaso-visto')||'';}catch{}if(!w||seen===w.created_at||Date.now()-Date.parse(w.created_at)>4*864e5)return '';
 const li=(xs,f)=>xs.length?`<ul>${xs.slice(0,5).map(f).join('')}</ul>${xs.length>5?`<small class="muted">y ${xs.length-5} más</small>`:''}`:'<p class="muted">Nada.</p>';
 return `<section class="panel wk"><div class="wk-h"><span class="wk-ic">${I('calendar',22)}</span><div><span class="eyebrow">REPASO DE LA SEMANA · ${short(w.from)} – ${short(w.to)}</span><h3>Así ha ido vuestra semana</h3></div><button class="icon-btn" data-action="weekly-close" title="Ocultar hasta el próximo domingo" aria-label="Ocultar">${I('close',18)}</button></div><p class="wk-text">${e(w.text)}</p>
  <div class="wk-cols"><div><b>${I('check',15)} Hecho <small>${w.done.length}</small></b>${li(w.done,x=>`<li>${e(x.title)}<small>${e(x.who)}</small></li>`)}</div><div><b>${I('arrow',15)} Lo que viene</b>${li(w.next,x=>`<li>${e(x.title)}<small>${short(x.date)}${x.time?' · '+e(x.time):''}</small></li>`)}</div><div><b>${I('alert',15)} Pendiente entre los dos</b>${li(w.pending,x=>`<li class="${x.late?'late':''}">${e(x.title)}<small>${x.late?'atrasado · ':x.blocked?'parado · ':''}${e(x.who)}</small></li>`)}</div></div>
  ${w.spent?`<p class="wk-spent">${I('wallet',15)} Gastado en planes juntos: <b>${euro(w.spent)}</b></p>`:''}</section>`;}
// Recuerdos: línea del tiempo con fotos, viajes y planes vividos; «tal día como hoy».
function momentsTimeline(items){const td=todayK(),md=td.slice(5),near=d=>{if(!d||d.slice(0,4)===td.slice(0,4))return false;const a=new Date('2000-'+d.slice(5)+'T12:00:00'),b=new Date('2000-'+md+'T12:00:00');return Math.abs(a-b)<=3*864e5;};
 const plans=(S.dash?.projects||[]).filter(p=>p.space==='couple'&&!p.archived&&(p.status==='done'||(p.end_date||p.start_date||'9')<td)).map(p=>({type:'plan',date:p.start_date||String(p.updated_at||'').slice(0,10),p}));
 const list=[...items.map(x=>({type:'mem',date:x.item_date||String(x.created_at||'').slice(0,10),x})),...plans].filter(z=>z.date).sort((a,b)=>b.date.localeCompare(a.date));
 if(!list.length)return '<div class="empty-mini">Vuestra línea del tiempo está vacía. Añadid el primer recuerdo: los viajes que terminéis aparecerán aquí solos.</div>';
 const card=z=>z.type==='mem'?`<div class="tl6-i">${cpItem(z.x)}</div>`:`<article class="tl6-i tl6-plan" data-project="${z.p.id}" role="link" tabindex="0">${coverUrl(z.p)?`<img src="${coverUrl(z.p)}" alt="${e(z.p.title)}" loading="lazy"/>`:`<div class="cp-mem-ph">${I(isTrip(z.p)?'plane':'heart',28)}</div>`}<div><span class="tl6-k">${isTrip(z.p)?'Viaje':'Plan'}</span><b>${e(z.p.title)}</b><small>${short(z.p.start_date||z.date)}${z.p.end_date&&z.p.end_date!==z.p.start_date?' – '+short(z.p.end_date):''}${z.p.destination?' · '+e(z.p.destination):''}</small></div></article>`;
 const otd=list.filter(z=>near(z.date)),years=[...new Set(list.map(z=>z.date.slice(0,4)))];
 return `${otd.length?`<section class="tl6-otd"><b>${I('heart',16)} Tal día como hoy</b><div>${otd.slice(0,3).map(z=>`<span>${z.date.slice(0,4)} · ${e(z.type==='mem'?z.x.title:z.p.title)}</span>`).join('')}</div></section>`:''}<div class="tl6">${years.map(y=>{const ys=list.filter(z=>z.date.startsWith(y));return `<section class="tl6-y"><h3><span>${y}</span><small>${ys.length} ${ys.length===1?'momento':'momentos'}</small></h3><div class="tl6-list">${ys.map(card).join('')}</div></section>`;}).join('')}</div>`;}
function homePage(){const projects=S.dash.projects.filter(p=>!p.archived),active=projects.filter(p=>p.status==='active').length,ideas=(S.dash.ideas||[]).filter(i=>i.state!=='converted').length;
 const tasks=projects.reduce((n,p)=>n+p.tasks_total,0),done=projects.reduce((n,p)=>n+p.tasks_done,0);
 return `<div class="page h6">${heroHtml()}${quickActions()}${weeklyCard()}<div class="h6-grid"><section class="panel h6-plans"><div class="panel-title"><h3>${I('calendar',18)} Próximos planes</h3><button class="text-btn" data-nav="dates">Ver todos ${I('arrow',15)}</button></div>${plansHtml()}</section><section class="panel h6-activity"><div class="panel-title"><h3>${I('activity',18)} Actividad reciente</h3><button class="text-btn" data-nav="activity">Ver toda la actividad ${I('arrow',15)}</button></div>${activityHtml(S.dash.recent.filter(a=>showSpace(a.space)).slice(0,5))}</section></div><div class="h6-grid">${ideaBox()}${duplaCard()}</div>${statusStrip()}<div class="section-heading"><div><span class="eyebrow">¿DÓNDE SEGUIMOS?</span><h2>Vuestros dos espacios</h2></div></div><div class="space-tiles"><button class="space-tile tile-work" data-nav="work"><div class="tile-head"><span class="tile-icon">${I('briefcase',25)}</span><span class="tile-index">01 / PROFESIONAL</span></div><div><h3>Trabajo <span>↗</span></h3><p>Ideas, aplicaciones, campañas, planes, tareas y proyectos para construir juntos.</p></div><div class="tile-foot"><span>${plural(projects.filter(p=>p.space==='work').length,'proyecto conjunto','proyectos conjuntos')}</span>${I('arrow',20)}</div></button><button class="space-tile tile-couple" data-nav="couple"><div class="tile-head"><span class="tile-icon">${I('heart',25)}</span><span class="tile-index">02 / NUESTRA VIDA</span></div><div><h3>Nuestro espacio <span>↗</span></h3><p>Viajes, cenas, citas, sorpresas, ideas y todos los planes que nos unen.</p></div><div class="tile-foot"><span>${plural(projects.filter(p=>p.space==='couple').length,'plan juntos','planes juntos')}</span>${I('arrow',20)}</div></button></div><div class="stat-grid">${kpi('layers','Proyectos compartidos',projects.length,'Siempre entre los dos')}${kpi('activity','En marcha',active,'Avanzando juntos')}${kpi('spark','Ideas guardadas',ideas,'A la espera de crecer')}${kpi('checkcircle','Tareas completadas',`${done}/${tasks}`,'Pequeñas victorias')}</div></div>`;}
// Texto del agente: escapado y con un markdown mínimo (negrita y listas).
function mdLite(s){return e(s).replace(/\*\*([^*]+)\*\*/g,'<b>$1</b>').replace(/(^|[\s(«"])\*([^*\n]+)\*(?=[\s).,;:!?»"]|$)/g,'$1<i>$2</i>').split(/\n{2,}/).map(par=>{const lines=par.split('\n');return lines.every(l=>/^\s*([-*•]|\d+[.)])\s+/.test(l))?`<ul>${lines.map(l=>`<li>${l.replace(/^\s*([-*•]|\d+[.)])\s+/,'')}</li>`).join('')}</ul>`:`<p>${lines.join('<br/>')}</p>`;}).join('');}
const PROPOSAL_STATUS={pending:'Pendiente de confirmar',done:'Hecho',rejected:'Descartado',failed:'No se pudo hacer',undone:'Deshecho'};
const UNDO_PATH={crear_proyecto:id=>'/api/projects/'+id,crear_tarea:id=>'/api/tasks/'+id,crear_evento:id=>'/api/events/'+id,anadir_gasto:id=>'/api/expenses/'+id,crear_idea:id=>'/api/ideas/'+id,crear_evento_calendario:id=>'/api/google/shared/events/'+encodeURIComponent(id)};
const canUndo=m=>m.proposals?.some(p=>p.status==='done'&&p.result_id&&UNDO_PATH[p.tool]);
function proposalsHtml(m){if(!m.proposals?.length)return '';const pending=m.proposals.filter(p=>p.status==='pending').length;
 return `<div class="dupla-props"><div class="dupla-props-head"><b>${m.proposals.length===1?'Propuesta':'Propuestas'} de Dupla</b><small>Nada se guarda hasta que lo confirmes.</small></div>${m.proposals.map(p=>`<div class="dupla-prop ${p.status}"><span class="dupla-prop-ic">${I(p.status==='done'?'checkcircle':p.status==='failed'?'alert':p.status==='rejected'?'close':'plus',16)}</span><span class="dupla-prop-main"><b>${e(p.summary)}</b><small>${PROPOSAL_STATUS[p.status]||p.status}${p.error?' · '+e(p.error):''}</small></span>${p.status==='pending'?`<button class="btn subtle" data-action="dupla-reject" data-msg="${m.id}" data-prop="${p.id}">Descartar</button><button class="btn primary" data-action="dupla-confirm" data-msg="${m.id}" data-prop="${p.id}">Hacer</button>`:''}</div>`).join('')}${pending>1?`<div class="dupla-props-all"><button class="btn primary" data-action="dupla-confirm" data-msg="${m.id}" data-prop="all">${I('check',16)} Confirmar las ${pending}</button></div>`:''}${canUndo(m)?`<div class="dupla-props-all"><button class="btn subtle" data-action="dupla-undo" data-msg="${m.id}">${I('undo',15)} Deshacer lo confirmado</button></div>`:''}</div>`;}
function duplaPage(){const a=S.agent||{messages:[],memory:[]},scope=S.prefs?.agent_scope||'all',hero=S.shared?.dupla_avatar_v?`/api/agent/avatar?v=${S.shared.dupla_avatar_v}`:'/dupla-agente.jpg?v=1',rec=S.duplaRec;
 return `<div class="page dupla-page"><div class="dupla-layout"><section class="dupla-chat dp-panel"><header class="dp-head">${DUPLA_LOGO}<div><h1>Dupla</h1><small>Vuestro agente personal de pareja · ${a.available===false?'IA no disponible':'actúa en DUPLA con vuestra confirmación'}</small></div><div class="dupla-scope" role="group" aria-label="Qué puede ver Dupla">${[['all','Todo'],['couple','Nuestro espacio'],['work','Trabajo']].map(([v,l])=>`<button class="${scope===v?'active':''}" data-action="dupla-scope" data-scope="${v}" aria-pressed="${scope===v}">${l}</button>`).join('')}</div></header>
 <div class="dupla-thread" id="dupla-thread" aria-live="polite"><div class="dp-hero ${a.messages.length?'compact':''}"><img src="${hero}" alt="Dupla, vuestro agente"/><span class="dp-spark s1"></span><span class="dp-spark s2"></span></div>
 ${a.messages.length?'':`<div class="dp-hello"><p>¡Hola! 😊<br/>Soy Dupla, vuestro agente. Puedo planificar viajes, crear itinerarios, organizar tareas, recordar fechas importantes, preparar vuestros PDF y revisar qué va mal… y lo hago yo, siempre con vuestra confirmación.</p><p><b>¿Qué os apetece hacer hoy?</b></p></div>`}
 ${a.messages.map(m=>`<div class="dupla-msg ${m.role}">${m.role==='assistant'?duplaAvatar():''}<div class="dupla-bubble">${mdLite(m.content)}${proposalsHtml(m)}<time>${since(m.created_at)}</time></div></div>`).join('')}${S.agentBusy?`<div class="dupla-msg assistant">${duplaAvatar()}<div class="dupla-bubble typing"><i></i><i></i><i></i></div></div>`:''}</div>
 <div class="dp-sugs">${DUPLA_SUGGESTIONS.map(x=>`<button class="dp-sug" data-action="ask-dupla" data-prompt="${e(x)}">${e(x)}</button>`).join('')}</div>
 <form class="dp-form" data-dupla-form="page"><button type="button" class="dp-mic ${rec?'rec':''}" data-action="dupla-voice" aria-label="${rec?'Parar y enviar':'Hablar a Dupla'}" title="${rec?'Parar y enviar':'Hablar (dictado)'}">${rec?'<i></i>':`<svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><rect x="9" y="3" width="6" height="11" rx="3"/><path d="M5 11a7 7 0 0 0 14 0M12 18v3"/></svg>`}</button><textarea name="message" rows="1" maxlength="2000" placeholder="${rec?'Te escucho… pulsa el círculo rojo para enviar':'Escribe un mensaje…'}" required ${S.agentBusy||rec?'disabled':''}></textarea><button class="dp-send" type="submit" aria-label="Enviar" ${S.agentBusy?'disabled':''}>${I('arrow',18)}</button></form></section>
 <aside class="dupla-side"><section class="panel"><h3>${I('lock',17)} Cómo trabaja Dupla</h3><ul class="dupla-rules"><li>Consulta vuestros datos reales antes de responder.</li><li>Propone los cambios y <b>espera vuestra confirmación</b>; luego lo podéis <b>deshacer</b>.</li><li>Solo ve el espacio que elijáis arriba.</li><li>Todo lo que hace queda en Actividad.</li></ul></section>
 <section class="panel dp-daily"><h3>${I('sun',17)} Resumen de cada mañana</h3><p class="hint">A las 8:00 os llega un aviso con lo del día (eventos, tareas que vencen, reservas del próximo viaje) y, si lo tenéis activado, un evento «☀️ Resumen del día» en vuestro calendario de Google para que el móvil os avise aunque DUPLA esté cerrada.</p><div class="buttons-inline"><button class="btn outline" data-action="daily-now">${I('bell',15)} Enviar el de hoy ahora</button><button class="btn subtle" data-nav="settings" data-settings-tab="notificaciones">Ajustes</button></div></section>
 <section class="panel"><div class="panel-title"><h3>${I('heart',17)} Lo que Dupla recuerda</h3></div><p class="hint">Preferencias, alergias, presupuesto habitual… Corregidlo o borradlo cuando queráis.</p>${a.memory?.length?`<ul class="dupla-memory">${a.memory.map(x=>S.memEdit===x.id?`<li><form class="dp-memf" data-mem="${x.id}"><input name="fact" maxlength="300" required value="${e(x.fact)}"/><button class="btn primary" type="submit">Guardar</button><button class="btn subtle" type="button" data-action="dupla-mem-edit" data-id="">Cancelar</button></form></li>`:`<li><span>${e(x.fact)}<small>${e(x.author||'')} · ${short(x.created_at)}</small></span><button class="icon-btn" data-action="dupla-mem-edit" data-id="${x.id}" aria-label="Corregir">${I('edit',15)}</button><button class="icon-btn" data-action="dupla-forget" data-id="${x.id}" aria-label="Olvidar">${I('trash',15)}</button></li>`).join('')}</ul>`:'<p class="hint">Todavía nada.</p>'}<form class="dp-memf" data-mem="new"><input name="fact" maxlength="300" required placeholder="Añadir: «Angie no come marisco»"/><button class="btn outline" type="submit">${I('plus',15)} Añadir</button></form></section>${a.messages.length?`<button class="btn outline full" data-action="dupla-clear">${I('trash',15)} Borrar mi conversación</button>`:''}</aside></div></div>`;}
// Voz: graba un audio corto y Whisper lo transcribe; se envía directamente a Dupla.
async function duplaVoice(){if(S.duplaRec){S.duplaRec.stop();return;}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw Error('Este navegador no permite grabar audio.');
 const stream=await navigator.mediaDevices.getUserMedia({audio:true}),type=['audio/webm;codecs=opus','audio/mp4','audio/ogg;codecs=opus'].find(t=>MediaRecorder.isTypeSupported(t))||'',rec=new MediaRecorder(stream,type?{mimeType:type}:{}),chunks=[];
 rec.ondataavailable=ev=>ev.data.size&&chunks.push(ev.data);const limit=setTimeout(()=>rec.state!=='inactive'&&rec.stop(),60000);
 rec.onstop=async()=>{clearTimeout(limit);stream.getTracks().forEach(t=>t.stop());S.duplaRec=null;render();const blob=new Blob(chunks,{type:rec.mimeType});if(blob.size<2000){toast('No he oído nada. Prueba otra vez.','error');return;}
  try{toast('Pasando tu voz a texto…');const b64=await new Promise(ok=>{const fr=new FileReader();fr.onload=()=>ok(String(fr.result).split(',')[1]);fr.readAsDataURL(blob);});const r=await api('/api/agent/voice','POST',{base64:b64});if(!r.text){toast('No he entendido nada. Prueba otra vez.','error');return;}await sendToDupla(r.text);}catch(ex){toast(ex.message,'error');}};
 rec.start();S.duplaRec=rec;render();}
// Deshacer lo confirmado de un mensaje: borra lo creado, en orden inverso.
async function undoMessage(msgId){const msg=S.agent?.messages.find(m=>m.id===msgId);if(!msg)throw Error('No encuentro ese mensaje.');let ok=0;
 for(const p of [...msg.proposals].reverse()){if(p.status!=='done'||!p.result_id||!UNDO_PATH[p.tool])continue;try{await api(UNDO_PATH[p.tool](p.result_id),'DELETE');}catch(ex){if(!/404|no encontrad/i.test(ex.message))throw ex;}p.status='undone';ok++;await api(`/api/agent/messages/${msgId}/proposals/${p.id}`,'PATCH',{status:'undone'}).catch(()=>{});}
 await loadDash();return ok;}
async function pdfForProject(id,kind){await loadProject(id);if(kind==='quote'){const r=await api('/api/projects/'+id+'/quote');if(!r.quote)throw Error('Ese proyecto aún no tiene presupuesto para cliente guardado.');S.quote=r.quote;S.quoteFor=id;await quotePdf(S.project);}else pdfReady(await buildPdf(S.project,kind));}
async function sendToDupla(message){message=String(message||'').trim();if(!message||S.agentBusy)return;S.agent=S.agent||{messages:[],memory:[]};
 S.agent.messages.push({id:'tmp',role:'user',content:message,proposals:[],created_at:new Date().toISOString()});S.agentBusy=true;if(S.view!=='dupla'){S.view='dupla';S.project=null;}render();scrollDupla();
 try{const r=await api('/api/agent','POST',{message,scope:S.prefs?.agent_scope||'all'});S.agent=await api('/api/agent');if(r.message?.trace?.some(t=>!t.ok))console.info('Dupla: herramientas con aviso',r.message.trace);}
 catch(ex){S.agent.messages=S.agent.messages.filter(m=>m.id!=='tmp');toast(ex.message,'error');}finally{S.agentBusy=false;render();scrollDupla();}}
function scrollDupla(){const t=$('#dupla-thread');if(t)t.scrollTop=t.scrollHeight;}
async function runProposals(msgId,which){const msg=S.agent?.messages.find(m=>m.id===msgId);if(!msg)return;const list=msg.proposals.filter(p=>p.status==='pending'&&(which==='all'||p.id===which));let ok=0;
 for(const p of list){try{let path=p.path;if(p.depends_on){const dep=msg.proposals.find(x=>x.id===p.depends_on);if(!dep?.result_id)throw Error('Primero confirma: '+(dep?.summary||'el proyecto'));path=path.replace(`{{${p.depends_on}}}`,dep.result_id);}
   let r=null;if(p.method==='PDF')await pdfForProject(p.body.project_id,p.body.kind);else if(p.method==='UNDO')await undoMessage(p.body.message_id);else r=await api(path,p.method,p.body);p.result_id=r?.project?.id||r?.item?.id||r?.idea?.id||(p.tool==='crear_evento_calendario'?r?.id:null)||null;p.status='done';ok++;await api(`/api/agent/messages/${msgId}/proposals/${p.id}`,'PATCH',{status:'done',...(p.result_id?{result_id:p.result_id}:{})});}
  catch(ex){p.status='failed';p.error=ex.message;try{await api(`/api/agent/messages/${msgId}/proposals/${p.id}`,'PATCH',{status:'failed',error:ex.message});}catch{}}}
 await loadDash();render();toast(ok===list.length?`Hecho: ${ok} ${ok===1?'cambio guardado':'cambios guardados'} para los dos.`:`${ok} de ${list.length} hechos. Revisa los que fallaron.`,ok===list.length?'ok':'error');}
function recentHtml(items){return items?.length?`<div class="activity-list">${items.map(a=>`<button class="activity-line" data-project="${a.project_id||''}"><span class="mini-ava">${e(initials(a.author||'?'))}</span><div><p><b>${e(a.author||'Alguien')}</b> ${e(a.action)} ${a.detail?`<strong>${e(a.detail)}</strong>`:''}</p><small>${e(a.project_title|| (a.space==='work'?'Trabajo':'Planes'))} · ${fmt(a.created_at)}</small></div><span class="activity-time">${new Date(a.created_at).toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit'})}</span></button>`).join('')}</div>`:'<div class="empty-mini">Aún no hay actividad. Vuestra primera idea está esperando.</div>';}
function upcomingLine(x){return `<button class="upcoming" data-project="${x.project_id}"><div class="date-chip"><b>${new Date(x.date+'T12:00:00').getDate()}</b><small>${new Date(x.date+'T12:00:00').toLocaleDateString('es-ES',{month:'short'})}</small></div><div class="upcoming-info"><b>${e(x.title)}</b><span>${e(x.project_title)}</span></div><span class="space-pill ${x.space}">${x.space==='work'?'Trabajo':'Planes'}</span></button>`;}
function progressHtml(done,total){return `<div class="progress"><div style="width:${pct(done,total)}%"></div></div>`;}
function projectCard(p){return `<button class="project-card" data-project="${p.id}"><div class="card-top"><span class="project-icon ${colorTag(p.color)}">${I(p.space==='work'?'briefcase':'heart',21)}</span><span class="status status-${p.status}">${I(STATUS_ICON[p.status],13)} ${STATUS[p.status]}</span></div><h3>${e(p.title)}</h3><p>${e(p.description||'Un espacio listo para desarrollar esta idea entre los dos.')}</p><div class="card-bottom"><div class="card-progress"><div class="progress-label"><span>${p.tasks_done}/${p.tasks_total} tareas</span><b>${pct(p.tasks_done,p.tasks_total)}%</b></div>${progressHtml(p.tasks_done,p.tasks_total)}</div><div class="card-bottom-row"><div class="avatar-stack">${S.dash.users.map((u,i)=>avatar(u.name,i===0?'av-first':'av-second')).join('')}</div><span>${I('clock',13)} ${short(p.updated_at)}</span><span class="card-go">${I('arrow',17)}</span></div></div></button>`;}
function renderCards(){const root=$('#project-grid');if(!root)return;const projects=S.dash.projects.filter(p=>p.space===S.space&&!p.archived&&(S.space!=='couple'||coupleKindOk(p))&&(S.filter==='all'||p.status===S.filter)&&(!S.query||(p.title+' '+p.description).toLocaleLowerCase('es').includes(S.query.toLocaleLowerCase('es'))));root.innerHTML=projects.length?projects.map(projectCard).join(''):`<div class="empty-grid"><div class="empty-icon">${I('spark',30)}</div><h3>Este espacio está listo para empezar.</h3><p>${S.query||S.filter!=='all'?'No hay resultados con esos filtros.':'Cread vuestra primera idea, añadid tareas y desarrolladla juntos.'}</p><button class="btn primary" data-action="new-project" data-space="${S.space}">${I('plus',17)} Crear proyecto</button></div>`;}
