 const line=(a,b,bold)=>{doc.text(t(a,10,bold?'bold':'normal'),M,y);doc.text(t(b,10,bold?'bold':'normal'),W-M,y,{align:'right'});y+=7;doc.setDrawColor(226,230,238);doc.line(M,y-4.5,W-M,y-4.5);};
