const ACT_TYPES=[['projects','Proyectos','folder'],['tasks','Tareas','checkcircle'],['ideas','Ideas','spark'],['events','Planes y calendario','calendar'],['trip','Viajes','plane'],['budget','Presupuesto','wallet'],['files','Archivos y notas','file'],['comments','Conversación','message'],['other','Otros','activity']];
function actType(a){const t=String(a.action).toLowerCase();return /viaje|itinerario|actividad|reserva/.test(t)?'trip':/coment|mensaje/.test(t)?'comments':/gasto|presupuesto/.test(t)?'budget':/idea/.test(t)?'ideas':/tarea|hito|checklist/.test(t)?'tasks':/plan|evento|fecha|calendario/.test(t)?'events':/archivo|enlace|nota|secci|portada/.test(t)?'files':/proyecto|estado|archiv/.test(t)?'projects':'other';}
async function loadActivity(more){const f=S.actF||(S.actF={user:'',space:'',project:'',type:''}),q=new URLSearchParams();for(const k of ['user','space','project'])if(f[k])q.set(k,f[k]);if(more&&S.actData?.items?.length)q.set('before',S.actData.items[S.actData.items.length-1].created_at);
 const r=await api('/api/activity?'+q);S.actData=more?{items:[...S.actData.items,...r.items],more:r.more}:r;}
