var MT={pc:null,local:null,remote:null,poll:null,rec:null,recTimer:null,after:0,t0:0,busy:false,polite:false,making:false};
const mtTime=ms=>`${Math.floor(ms/60000)}:${String(Math.floor(ms/1000)%60).padStart(2,'0')}`;
async function loadMeetings(){S.meetings=(await api('/api/meetings')).items;}
async function openMeeting(id){S.meetingId=id;S.meetingData=await api('/api/meetings/'+id);nav('meetings');S.meetingId=id;render();}
function meetingsPage(){const ms=S.meetings||[],ps=(S.dash?.projects||[]).filter(p=>!p.archived),ideas=(S.dash?.ideas||[]).filter(i=>!i.archived_at&&i.state!=='converted'),pre=S.meetingPre||{};
 const ctx=x=>x.project_title?`${x.project_kind==='trip'||x.destination?'Viaje':x.space==='work'?'Proyecto de trabajo':'Proyecto personal'} · ${e(x.project_title)}`:x.idea_title?`Idea · ${e(x.idea_title)}`:'Sin vincular';
 return `<div class="page mt-page"><div class="page-heading"><span class="eyebrow">HABLAR Y QUE QUEDE GUARDADO</span><h1>Reuniones<span class="title-dot">.</span></h1><p>Videollamada entre los dos desde DUPLA. Cada uno transcribe su micrófono; la transcripción se guarda tal cual y el resumen va aparte.</p></div>
 <form id="meeting-form" class="panel mt-new"><label>Título<input name="title" required maxlength="160" value="${e(pre.title||'')}" placeholder="Planear Lisboa, revisar la web…"/></label><label>Vincular a<select name="link"><option value="">Sin vincular</option><optgroup label="Proyectos de trabajo">${ps.filter(p=>p.space==='work').map(p=>`<option value="p:${p.id}" ${pre.project_id===p.id?'selected':''}>${e(p.title)}</option>`).join('')}</optgroup><optgroup label="Viajes">${ps.filter(p=>p.space==='couple'&&isTrip(p)).map(p=>`<option value="p:${p.id}" ${pre.project_id===p.id?'selected':''}>${e(p.title)}</option>`).join('')}</optgroup><optgroup label="Proyectos personales">${ps.filter(p=>p.space==='couple'&&!isTrip(p)).map(p=>`<option value="p:${p.id}" ${pre.project_id===p.id?'selected':''}>${e(p.title)}</option>`).join('')}</optgroup><optgroup label="Ideas">${ideas.map(i=>`<option value="i:${i.id}">${e(i.title)}</option>`).join('')}</optgroup></select></label><label>Cómo<select name="kind">${S.sharedCalendar?.created?`<option value="meet" selected>Google Meet + transcripción</option>`:''}<option value="dupla">Videollamada DUPLA</option></select></label><label class="mt-when">Día<input type="date" name="date" value="${todayK()}"/></label><label class="mt-when">Hora<input type="time" name="time" value="${new Date(Date.now()+36e5).toTimeString().slice(0,2)}:00"/></label><button class="btn primary" type="submit">${I('video',16)} Crear reunión</button></form>
 <section class="panel mt-list">${ms.length?ms.map(x=>`<button class="mt-row" data-action="meeting-open" data-id="${x.id}"><span class="mt-ic st-${x.status}">${I('video',18)}</span><span class="mt-b"><b>${e(x.title)}</b><small>${ctx(x)} · ${fmt(x.created_at)}${x.segments?` · ${x.segments} tramos transcritos`:''}${x.summary_at?' · con resumen':''}</small></span><span class="mt-st st-${x.status}">${{scheduled:'Pendiente',live:'En curso',ended:'Terminada'}[x.status]}</span>${I('arrow',15)}</button>`).join(''):'<div class="empty-mini">Aún no hay reuniones.</div>'}</section></div>`;}
function meetingRoom(){const d=S.meetingData;if(!d)return '<div class="page"><p class="hint">Cargando…</p></div>';const m=d.meeting,segs=d.segments||[],inCall=!!MT.pc,users=S.dash?.users||[];
 const who=id=>{const i=users.findIndex(u=>u.id===id);return i<0?'':i===0?'av-first':'av-second';};
 return `<div class="page mt-room"><button class="back-link dark" data-action="meeting-back">${I('back',16)} Reuniones</button><div class="mt-head"><div><h1>${e(m.title)}</h1><p>${m.project_title?`${I('folder',14)} <button class="link-btn" data-project="${m.project_id}">${e(m.project_title)}</button>`:m.idea_title?`${I('spark',14)} ${e(m.idea_title)}`:'Sin vincular'} · <span class="mt-st st-${m.status}">${{scheduled:'Pendiente',live:'En curso',ended:'Terminada'}[m.status]}</span></p></div>
 <div class="mt-ctrl">${m.meet_url?(MT.tx?`<span class="mt-rec"><i></i> Grabando y transcribiendo tu micro</span><a class="btn outline" href="${e(m.meet_url)}" target="_blank" rel="noopener noreferrer">${I('video',16)} Volver a Meet</a><button class="btn danger-light" data-action="mt-hang">${I('close',16)} Parar</button>`:inCall?'':`<button class="btn primary" data-action="mt-meet-start" data-url="${e(m.meet_url)}">${I('video',16)} Abrir Meet y transcribir</button><button class="btn subtle" data-action="mt-tx">${I('message',16)} Solo transcribir</button>`):''}${MT.tx?'':inCall?`<button class="btn outline" data-action="mt-mic">${I('phone',16)} ${MT.local?.getAudioTracks()[0]?.enabled===false?'Activar micro':'Silenciar'}</button><button class="btn outline" data-action="mt-cam">${I('camera',16)} ${MT.local?.getVideoTracks()[0]?.enabled===false?'Activar cámara':'Apagar cámara'}</button><button class="btn danger-light" data-action="mt-hang">${I('close',16)} Colgar</button>`:`<button class="btn primary" data-action="mt-join">${I('video',16)} ${m.status==='live'?'Unirse':'Empezar videollamada'}</button>${m.status==='live'?`<button class="btn outline" data-action="mt-end">Terminar reunión</button>`:''}`}<button class="icon-btn" data-action="mt-del" title="Eliminar reunión">${I('trash',16)}</button></div></div>
 <div class="mt-video ${inCall?'on':''}"><div class="mt-v"><video id="mt-remote" autoplay playsinline></video><span>${inCall?(MT.remote?'Conectado':'Esperando a la otra persona…'):'La videollamada empieza al pulsar el botón'}</span></div><div class="mt-v me"><video id="mt-local" autoplay playsinline muted></video><span>Tú${MT.rec?' · transcribiendo tu micro':''}</span></div></div>
 ${!d.ai?`<p class="hint mt-warn">${I('alert',14)} La transcripción necesita la IA del servidor (Workers AI); sin ella la llamada funciona pero no se transcribe.</p>`:''}
 <section class="panel mt-tr"><div class="panel-title"><h3>${I('message',18)} Transcripción completa</h3><span class="mini-label">Automática (Whisper), tal cual se reconoció · sin editar ni resumir</span>${segs.length?`<a class="btn subtle" href="/api/meetings/${m.id}/transcript">${I('download',15)} Descargar</a>`:''}</div>${segs.length?segs.map(x=>`<div class="mt-seg"><span class="mt-t">${mtTime(x.t_start)}</span>${avatar(x.speaker||'?',who(x.user_id))}<div><b>${e(x.speaker||'')}${x.has_audio?` <button class="mt-play" data-action="mt-play" data-sid="${x.id}" title="Escuchar lo que dijo" aria-label="Escuchar">▶</button>`:''}</b><p>${e(x.text)}</p></div></div>`).join(''):'<p class="hint">Todavía no hay transcripción. Se va guardando cada 30 segundos mientras habláis: cada uno debe tener DUPLA abierta en su dispositivo grabando su micrófono. Al terminar, el resumen se hace solo.</p>'}</section>
 <section class="panel mt-ai"><div class="panel-title"><h3>${I('spark',18)} Resumen y análisis</h3><span class="mini-label">Generado por IA a partir de la transcripción · no es la transcripción</span></div>${m.summary_at?`<div class="mt-sum"><h4>Resumen</h4><p>${e(m.summary)}</p><h4>Acciones / tareas detectadas</h4>${m.tasks.length?`<ul class="mt-tasks">${m.tasks.map((t,k)=>`<li><span>${e(t.title)}${t.who?` <small>· ${e(t.who)}</small>`:''}</span>${m.project_id?`<button class="btn subtle" data-action="mt-task" data-k="${k}" ${S.mtDone?.[m.id+k]?'disabled':''}>${I('plus',14)} ${S.mtDone?.[m.id+k]?'Creada':'Crear tarea'}</button>`:''}</li>`).join('')}</ul>`:'<p class="hint">No se detectaron tareas.</p>'}${m.project_id&&m.tasks.length?`<button class="btn primary" data-action="mt-tasks-all">${I('plus',15)} Crear todas las tareas en el proyecto</button>`:''}<h4>Decisiones</h4>${m.decisions.length?`<ul>${m.decisions.map(x=>`<li>${e(x)}</li>`).join('')}</ul>`:'<p class="hint">No se detectaron decisiones.</p>'}<small class="hint">Generado ${fmt(m.summary_at)}</small></div>`:''}<button class="btn ${m.summary_at?'outline':'primary'}" data-action="mt-sum" ${segs.length&&d.ai?'':'disabled'}>${I('spark',16)} ${m.summary_at?'Volver a generar':'Generar resumen, tareas y decisiones'}</button></section></div>`;}
async function mtSignal(data){await api('/api/meetings/'+S.meetingId+'/signal','POST',{data});}
function mtAttach(){const l=$('#mt-local'),r=$('#mt-remote');if(l&&MT.local&&l.srcObject!==MT.local)l.srcObject=MT.local;if(r&&MT.remote&&r.srcObject!==MT.remote)r.srcObject=MT.remote;}
async function mtJoin(){const id=S.meetingId,m=S.meetingData.meeting;if(!navigator.mediaDevices?.getUserMedia)throw Error('Este navegador no permite videollamadas.');
 MT.local=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true},video:{width:{ideal:640},height:{ideal:480},facingMode:'user'}}).catch(()=>navigator.mediaDevices.getUserMedia({audio:true}));
 const r=await api('/api/meetings/'+id+'/start','POST',{});S.meetingData.meeting={...m,...r.meeting,tasks:m.tasks,decisions:m.decisions};MT.t0=new Date(r.meeting.started_at).getTime();
 const other=(S.dash?.users||[]).find(u=>u.id!==S.me.id);MT.polite=!other||S.me.id>other.id;MT.after=(await api('/api/meetings/'+id+'/signal?after=999999999')).last;
 const ice=await api('/api/rtc/ice').catch(()=>({iceServers:[{urls:['stun:stun.cloudflare.com:3478','stun:stun.l.google.com:19302']}]}));MT.turn=!!ice.turn;
 const pc=MT.pc=new RTCPeerConnection({iceServers:ice.iceServers});
 for(const t of MT.local.getTracks())pc.addTrack(t,MT.local);
 pc.ontrack=ev=>{MT.remote=ev.streams[0];render();};
 pc.onicecandidate=ev=>{if(ev.candidate)mtSignal({type:'ice',c:ev.candidate.toJSON()}).catch(()=>{});};
 pc.onnegotiationneeded=async()=>{try{MT.making=true;await pc.setLocalDescription();await mtSignal({type:'sdp',d:pc.localDescription});}finally{MT.making=false;}};
 pc.onconnectionstatechange=()=>{if(['failed','disconnected'].includes(pc.connectionState)){MT.remote=null;render();if(pc.connectionState==='failed')pc.restartIce();}};
 await mtSignal({type:'hello'});
 MT.poll=setInterval(async()=>{try{const r=await api('/api/meetings/'+id+'/signal?after='+MT.after);for(const x of r.items){MT.after=Math.max(MT.after,x.id);const d=x.data||{};
  if(d.type==='hello'&&!MT.polite){MT.making=true;try{await pc.setLocalDescription(await pc.createOffer({iceRestart:true}));await mtSignal({type:'sdp',d:pc.localDescription});}finally{MT.making=false;}}
  else if(d.type==='sdp'){const coll=d.d.type==='offer'&&(MT.making||pc.signalingState!=='stable');if(coll&&!MT.polite)continue;await pc.setRemoteDescription(d.d);if(d.d.type==='offer'){await pc.setLocalDescription();await mtSignal({type:'sdp',d:pc.localDescription});}}
  else if(d.type==='ice'){try{await pc.addIceCandidate(d.c);}catch{}}
  else if(d.type==='bye'){MT.remote=null;render();}}}catch(ex){console.warn('Señal',ex);}},1200);
 if(S.meetingData.ai)mtRecord();render();mtAttach();}
// Cada navegador graba SOLO su micrófono en tramos independientes de 30 s y los manda a transcribir.
function mtRecord(){const tr=MT.local?.getAudioTracks()[0];if(!tr||!window.MediaRecorder)return;const type=['audio/webm;codecs=opus','audio/mp4','audio/ogg;codecs=opus'].find(t=>MediaRecorder.isTypeSupported(t))||'';
 const start=()=>{if(!MT.pc&&!MT.tx)return;const st=Date.now()-MT.t0,rec=new MediaRecorder(new MediaStream([tr]),type?{mimeType:type}:{});const chunks=[];rec.ondataavailable=ev=>ev.data.size&&chunks.push(ev.data);
  rec.onstop=async()=>{const blob=new Blob(chunks,{type:rec.mimeType});if(MT.pc||MT.tx)start();if(blob.size<3000||!tr.enabled)return;try{const b64=await new Promise(ok=>{const fr=new FileReader();fr.onload=()=>ok(String(fr.result).split(',')[1]);fr.readAsDataURL(blob);});const r=await api('/api/meetings/'+S.meetingId+'/audio','POST',{t_start:Math.max(0,st),base64:b64,mime:rec.mimeType});if(r.segment&&S.meetingData){S.meetingData.segments=[...S.meetingData.segments,r.segment].sort((a,b)=>a.t_start-b.t_start);if(S.view==='meetings')render();}}catch(ex){console.warn('Transcripción',ex);}};
  MT.rec=rec;rec.start();MT.recTimer=setTimeout(()=>{if(rec.state!=='inactive')rec.stop();},30000);};start();}
// Con Google Meet: DUPLA solo graba TU micrófono (cada uno el suyo) y lo transcribe; la llamada va por Meet.
async function mtTranscribe(){if(!S.meetingData.ai)throw Error('La transcripción necesita la IA del servidor.');MT.local=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true}});
 const r=await api('/api/meetings/'+S.meetingId+'/start','POST',{});MT.t0=new Date(r.meeting.started_at).getTime();MT.tx=true;mtRecord();render();toast('Transcribiendo tu micrófono. Deja esta pestaña abierta mientras habláis en Meet.');}
async function mtHang(){const pc=MT.pc;MT.pc=null;MT.tx=false;clearInterval(MT.poll);clearTimeout(MT.recTimer);if(MT.rec?.state==='recording')MT.rec.stop();MT.rec=null;try{await mtSignal({type:'bye'});}catch{}pc?.close();MT.local?.getTracks().forEach(t=>t.stop());MT.local=null;MT.remote=null;}
// ---- Tablero de tareas (independiente de los dos espacios) ----
const BD_COLS=[['todo','Pendiente'],['doing','En proceso'],['blocked','Parado'],['done','Terminado']],BD_PRIO={low:'Baja',normal:'Normal',high:'Alta',urgent:'Urgente'};
async function loadBoard(){S.board=(await api('/api/board')).items;}
function boardPage(){const items=S.board||[],users=S.dash?.users||[],who=S.boardWho||'all',t=todayK(),byId=Object.fromEntries(items.map(x=>[x.id,x]));
 const vis=items.filter(x=>who==='all'||(who==='none'?!x.assignee:x.assignee===who));
 const card=x=>{const par=x.parent_id&&byId[x.parent_id],locked=par&&par.status!=='done',kids=items.filter(y=>y.parent_id===x.id),ui=users.findIndex(u=>u.id===x.assignee),col=BD_COLS.findIndex(c=>c[0]===x.status);
  return `<article class="bd-card p-${x.priority} ${x.status==='done'?'is-done':''}" draggable="true" data-bd="${x.id}"><div class="bd-top"><span class="bd-prio">${BD_PRIO[x.priority]}</span>${x.due_date?`<span class="bd-due ${x.due_date<t&&x.status!=='done'?'late':''}">${I('clock',12)} ${short(x.due_date)}</span>`:''}</div><b>${e(x.title)}</b>${x.notes?`<p>${e(x.notes).slice(0,140)}</p>`:''}
  ${par?`<span class="bd-dep ${locked?'locked':''}">${I(locked?'lock':'checkcircle',12)} Depende de «${e(par.title)}»${locked?' · no se puede cerrar aún':''}</span>`:''}${kids.length?`<span class="bd-kids">${I('layers',12)} ${kids.filter(k=>k.status==='done').length}/${kids.length} subtareas</span>`:''}${tnChip(x.notes_count)}
  <div class="bd-foot">${x.assignee?`<span class="bd-who">${avatar(x.assignee_name||'?',ui===0?'av-first':'av-second')}${e((x.assignee_name||'').split(' ')[0])}</span>`:`<span class="bd-who both">${I('users',14)} Los dos</span>`}<span class="bd-btns"><button class="icon-btn" data-action="bd-move" data-id="${x.id}" data-to="${BD_COLS[col-1]?.[0]||''}" ${col<=0?'disabled':''} aria-label="Mover a la izquierda">‹</button><button class="icon-btn" data-action="bd-move" data-id="${x.id}" data-to="${BD_COLS[col+1]?.[0]||''}" ${col>=3?'disabled':''} aria-label="Mover a la derecha">›</button><button class="icon-btn" data-action="bd-edit" data-id="${x.id}" aria-label="Editar">${I('edit',14)}</button></span></div></article>`;};
 return `<div class="page bd-page"><div class="page-heading"><span class="eyebrow">LO QUE TENEMOS QUE HACER</span><h1>Tareas<span class="title-dot">.</span></h1><p>Un tablero solo vuestro, aparte de Trabajo y Nuestro espacio. Arrastrad las tarjetas entre columnas; el color indica la prioridad.</p></div>
 <div class="bd-bar"><div class="cal-seg">${[['all','Todas'],...users.map(u=>[u.id,u.name.split(' ')[0]]),['none','Los dos']].map(([v,l])=>`<button class="${who===v?'active':''}" data-action="bd-who" data-v="${v}">${e(l)}</button>`).join('')}</div><div class="bd-legend">${Object.entries(BD_PRIO).map(([k,l])=>`<span class="p-${k}"><i></i>${l}</span>`).join('')}</div><button class="btn primary" data-action="bd-new">${I('plus',16)} Nueva tarea</button></div>
 <div class="bd-board">${BD_COLS.map(([k,l])=>{const xs=vis.filter(x=>x.status===k);return `<section class="bd-col c-${k}" data-col="${k}"><h3>${l} <small>${xs.length}</small></h3><div class="bd-list">${xs.map(card).join('')||'<p class="bd-empty">Arrastra aquí</p>'}</div></section>`;}).join('')}</div></div>`;}
async function bdSave(id,patch){try{await api('/api/board/'+id,'PATCH',patch);}catch(ex){toast(ex.message,'error');}await loadBoard();render();}
// ---- Presupuestos: historial por destino y previsión ----
function rng(r){return r?(r.min===r.max?euro(r.min):`${euro(r.min)} – ${euro(r.max)}`):'—';}
function insightsHtml(x){if(!x||(!x.events?.length&&!x.tips?.length))return '';return `<div class="bg-ins"><h4>${I('spark',16)} Lo que suele pasar en esas fechas <small>según la IA · orientativo, comprobad fechas</small></h4>${x.events.map(v=>`<div class="bg-ev"><b>${e(v.name)}</b><small>${e(v.when)}</small><p>${e(v.impact)}</p>${v.tip?`<p class="bg-tip">${I('check',13)} ${e(v.tip)}</p>`:''}</div>`).join('')}${x.tips?.length?`<ul class="bg-tips">${x.tips.map(t=>`<li>${e(t)}</li>`).join('')}</ul>`:''}</div>`;}
const MES=['Todo el año','enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
function notesHtml(dest){const key=String(dest).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim(),ns=(S.destNotes||[]).filter(n=>n.dest_key===key);
 return `<div class="bg-notes"><h5>${I('bell',14)} Vuestros avisos de ${e(dest)}</h5>${ns.map(n=>`<div class="bg-note"><span><b>${e(MES[n.month])}</b> ${e(n.text)}</span><button class="icon-btn" data-action="dn-del" data-id="${n.id}" aria-label="Borrar">${I('trash',14)}</button></div>`).join('')||'<p class="hint">Apuntad lo que vayáis descubriendo (ferias, fiestas, obras, precios…) y saldrá en los próximos viajes.</p>'}<form class="bg-note-form" data-dest="${e(dest)}"><select name="month">${MES.map((m,i)=>`<option value="${i}">${m}</option>`).join('')}</select><input name="text" maxlength="300" required placeholder="Ej.: en mayo es San Isidro y los hoteles suben"/><button class="btn outline" type="submit">${I('plus',14)} Añadir</button></form></div>`;}
function tripAdvice(p){if(!p.destination||!p.start_date)return '';S.tripFc=S.tripFc||{};const k=p.id+p.start_date+(p.end_date||'');const f=S.tripFc[k];
 if(f===undefined){S.tripFc[k]=null;Promise.all([api(`/api/budget/forecast?destination=${encodeURIComponent(p.destination)}&start=${p.start_date}&end=${p.end_date||p.start_date}`),api('/api/budget/notes')]).then(([r,n])=>{S.tripFc[k]=r;S.destNotes=n.items;if(S.project?.id===p.id)render();}).catch(()=>{S.tripFc[k]=false;});}
 if(!f)return '';const al=f.alerts.filter(a=>a.level!=='low').slice(0,4);
 return `<section class="panel trip-adv"><h3>${I('alert',17)} Antes de reservar ${e(f.destination)}</h3>${al.map(a=>`<p class="bg-al l-${a.level}">${e(a.text)}</p>`).join('')}${f.estimate?`<p class="hint">Según vuestros viajes anteriores: ${rng(f.estimate.total)} en total.</p>`:''}${insightsHtml(f.insights)}<button class="link-btn" data-nav="budgets">Ver presupuestos e historial →</button></section>`;}
// Finanzas de la cuenta compartida: ingresos y gastos, presupuesto mensual por categoría, objetivos de ahorro y facturas.
const FIN_P=[['month','Mes'],['quarter','Trimestre'],['year','Año']],FIN_COL=[['#2f6fd8','Azul'],['#22a05a','Verde'],['#d6408a','Rosa'],['#e08a1e','Naranja'],['#7c4ddb','Morado'],['#14a3a3','Turquesa']],FIN_IC={plane:'Viaje',heart:'Pareja',lock:'Emergencias',home:'Casa',gift:'Regalo',star:'Capricho',camera:'Fotos y equipo',briefcase:'Trabajo',sun:'Vacaciones',wallet:'Ahorro'};
const feur=n=>Number(n||0).toLocaleString('es-ES',{style:'currency',currency:'EUR',maximumFractionDigits:0,useGrouping:'always'}),feur2=n=>Number(n||0).toLocaleString('es-ES',{style:'currency',currency:'EUR',useGrouping:'always'});
async function loadFin(){S.fin=await api('/api/finance?period='+(S.finPeriod||'month'));}
async function finDone(msg){S.modal=null;$('#modal-root').innerHTML='';await loadFin();render();toast(msg);}
const finCats=()=>Object.entries(S.fin.cats).filter(([k])=>k!=='ingreso').map(([k,[l]])=>[k,l]);
function finDelta(cur,prev,good){if(!prev)return `<small class="fin-d">${cur?'Sin datos del periodo anterior':'Sin movimientos'}</small>`;const p=Math.round((cur-prev)/prev*100),up=p>0;return `<small class="fin-d ${!p?'':(good==='up')===up?'ok':'bad'}">${!p?'=':up?'▲':'▼'} ${Math.abs(p)}% vs. ${e(S.fin.vs)}</small>`;}
function finChart(series){const max=Math.max(1,...series.flatMap(x=>[x.income,x.expense])),step=[50,100,250,500,1000,2000,2500,5000,10000,25000,50000].find(x=>x*3>=max)||Math.ceil(max/3),top=step*3,k=v=>v>=1000?(v/1000).toLocaleString('es-ES',{maximumFractionDigits:1})+'k':String(v);
 return `<div class="fin-chart" role="img" aria-label="Ingresos y gastos: ${series.map(x=>`${x.label} ${feur(x.income)} y ${feur(x.expense)}`).join(', ')}"><div class="fin-y">${[3,2,1,0].map(i=>`<span>${k(step*i)}</span>`).join('')}</div><div class="fin-cols">${series.map(x=>`<div class="fin-col ${x.current?'cur':''}"><div class="fin-bars"><i class="in" style="height:${(x.income/top*100).toFixed(1)}%" title="Ingresos ${feur2(x.income)}"></i><i class="out" style="height:${(x.expense/top*100).toFixed(1)}%" title="Gastos ${feur2(x.expense)}"></i></div><span>${e(x.label)}</span></div>`).join('')}</div></div>`;}
function finMoveRow(x,inModal){const c=S.fin.cats[x.category]||['Otros','#7d8597'],link=x.project_id?(inModal?'':`data-project="${x.project_id}"`):`data-action="fin-move" data-id="${x.id}"`;return `<${link?'button':'div'} class="fin-mv" ${link}><span class="fin-tag" style="--c:${c[1]}">${e(x.kind==='in'?'Ingreso':c[0])}</span><span class="fin-mv-t">${e(x.title)}${x.project_id?'<small>Gasto de un plan</small>':x.who?`<small>${x.kind==='in'?'Cobró':'Pagó'} ${e(x.who.split(' ')[0])}</small>`:''}</span><time>${short(x.date)}</time><b class="${x.kind==='in'?'pos':''}">${x.kind==='in'?'+':'−'}${feur2(x.amount)}</b></${link?'button':'div'}>`;}
function financePage(){const F=S.fin;if(!F)return '<div class="page"><p class="muted">Cargando finanzas…</p></div>';const k=F.kpis,per={month:'del mes',quarter:'del trimestre',year:'del año'}[F.period];
 const bud=F.budgets.map(b=>{const over=b.limit&&b.spent>b.limit,pct=b.limit?Math.min(100,b.spent/b.limit*100):100;return `<div class="fin-bud ${over?'over':''}"><div><span>${e(b.label)}</span><span><b>${feur(b.spent)}</b>${b.limit?` / ${feur(b.limit)}`:' · sin límite'}</span></div><div class="fin-bar"><i style="width:${pct.toFixed(1)}%;--c:${over?'#e04848':b.color}"></i></div></div>`;}).join('');
 const goals=F.goals.map(g=>`<button class="fin-goal" data-action="fin-goal" data-id="${g.id}"><span class="fin-gi" style="--c:${g.color}">${I(g.icon,18)}</span><span class="fin-gb"><span><b>${e(g.title)}</b><small>${feur(g.saved)} / ${feur(g.target)}</small></span><span class="fin-bar"><i style="width:${Math.min(100,g.saved/g.target*100).toFixed(1)}%;--c:${g.color}"></i></span></span></button>`).join('');
 const bills=F.bills.map(b=>`<div class="fin-bill ${b.due_date<F.today?'late':''}"><button data-action="fin-bill" data-id="${b.id}"><b>${e(b.title)}</b><small>${e(S.fin.cats[b.category]?.[0]||'')} · ${b.due_date<F.today?'venció el':'vence el'} ${short(b.due_date)}${b.repeat==='monthly'?' · cada mes':''}</small></button><strong>${feur2(b.amount)}</strong><button class="btn subtle" data-action="fin-pay" data-id="${b.id}">${I('check',15)} Pagar</button></div>`).join('');
 return `<div class="page fin-page"><div class="fin-head"><div class="page-heading"><span class="eyebrow">LA CUENTA DE LOS DOS</span><h1>Finanzas<span class="title-dot">.</span></h1><p>${e(F.label)} · Cuenta compartida</p></div><div class="fin-actions"><div class="st-seg" role="group" aria-label="Periodo">${FIN_P.map(([v,l])=>`<button class="${F.period===v?'active':''}" aria-pressed="${F.period===v}" data-action="fin-period" data-v="${v}">${l}</button>`).join('')}</div><button class="btn primary" data-action="fin-move">${I('plus',16)} Movimiento</button></div></div>
 <div class="fin-kpis"><div class="panel fin-k"><small>Ingresos</small><b>${feur(k.income)}</b>${finDelta(k.income,k.income_prev,'up')}</div><div class="panel fin-k"><small>Gastos</small><b>${feur(k.expense)}</b>${finDelta(k.expense,k.expense_prev,'down')}</div><div class="panel fin-k"><small>Ahorro ${per}</small><b class="${k.saving<0?'neg':'acc'}">${feur(k.saving)}</b><small class="fin-d">${k.saving_pct===null?'Sin ingresos apuntados':`${k.saving_pct}% de los ingresos`}</small></div><div class="panel fin-k"><small>Facturas pendientes</small><b>${k.bills_pending}</b><small class="fin-d">${k.bill_next?'Próxima: '+short(k.bill_next):'Ninguna por pagar'}</small></div></div>
 <div class="fin-row fin-row2"><section class="panel"><div class="fin-h"><h3>Ingresos y gastos</h3><span class="fin-legend"><i class="in"></i>Ingresos<i class="out"></i>Gastos</span></div>${finChart(F.series)}</section><section class="panel"><div class="fin-h"><h3>Presupuesto por categoría</h3><button class="btn subtle" data-action="fin-budgets">${I('edit',14)} Límites</button></div>${bud||'<p class="hint">Poned un límite mensual por categoría y aquí veréis cuánto lleváis gastado.</p>'}</section></div>
 <div class="fin-row"><section class="panel"><div class="fin-h"><h3>Objetivos de ahorro</h3><button class="btn subtle" data-action="fin-goal">${I('plus',14)} Objetivo</button></div>${goals||'<p class="hint">¿Para qué estáis ahorrando? Un viaje, un fondo de emergencia… Creadlo y apuntad lo que vais guardando.</p>'}</section><section class="panel"><div class="fin-h"><h3>Movimientos recientes</h3><button class="link-btn" data-action="fin-all">Ver todos ${I('arrow',13)}</button></div>${F.recent.length?F.recent.map(x=>finMoveRow(x)).join(''):'<p class="hint">Apuntad el primer ingreso o gasto con «Movimiento». Los gastos de vuestros viajes y planes ya cuentan solos.</p>'}</section></div>
 <section class="panel fin-bills"><div class="fin-h"><h3>Facturas pendientes</h3><button class="btn subtle" data-action="fin-bill">${I('plus',14)} Factura</button></div>${bills||'<p class="hint">Luz, internet, seguros… Apuntadlas con su fecha y DUPLA os avisa a los dos el día antes.</p>'}</section></div>`;}
function budgetsPage(){const h=S.budgetHist?.destinations||[],f=S.budgetFc,q=S.budgetQ||{};
 return `<div class="page bg-page"><div class="page-heading"><span class="eyebrow">VIAJAR SIN SUSTOS</span><h1>Presupuestos<span class="title-dot">.</span></h1><p>Lo que os gastasteis en cada destino, cuándo reservasteis y cuánto os costará la próxima vez, con avisos de festivos, puentes y temporada alta.</p></div>${S.balance?.paid?.some(x=>x.amount)?balanceHtml(S.balance):''}
 <section class="panel bg-calc"><h3>${I('plane',18)} Calcular el próximo viaje</h3><form id="bg-form" class="bg-form"><label>Destino<input name="destination" required list="bg-dest" value="${e(q.destination||'')}" placeholder="Zaragoza"/><datalist id="bg-dest">${h.map(d=>`<option value="${e(d.destination)}">`).join('')}</datalist></label><label>Desde<input type="date" name="start" required value="${e(q.start||'')}"/></label><label>Hasta<input type="date" name="end" required value="${e(q.end||'')}"/></label><label>Personas<input type="number" name="people" min="1" max="12" value="${e(q.people||2)}"/></label><button class="btn primary" type="submit">${I('wallet',16)} Calcular</button></form>
 ${f?`<div class="bg-result"><div class="bg-est"><h4>${e(f.destination)} · ${f.days} ${f.days===1?'día':'días'}, ${f.nights} ${f.nights===1?'noche':'noches'}</h4>${f.estimate?`<div class="bg-rows"><span>Alojamiento</span><b>${rng(f.estimate.stay)}</b><span>Comidas, cenas y salidas</span><b>${rng(f.estimate.food)}</b><span>Billetes y transporte</span><b>${rng(f.estimate.tickets)}</b><span class="bg-tot">Total estimado</span><b class="bg-tot">${rng(f.estimate.total)}</b></div><small>Según ${f.history.trips} ${f.history.trips===1?'viaje anterior':'viajes anteriores'} a este destino.</small>`:'<p class="hint">Aún no hay viajes guardados a este destino: cuando apuntéis los gastos de uno, DUPLA calculará el rango.</p>'}<small>Faltan ${f.lead_days} días.</small></div>
  <div class="bg-alerts"><h4>${I('alert',16)} Antes de reservar</h4>${f.alerts.map(a=>`<p class="bg-al l-${a.level}">${e(a.text)}</p>`).join('')}</div></div>${insightsHtml(f.insights)}${notesHtml(f.destination)}`:''}</section>
 <div class="bg-head"><h2>Historial por destino</h2><button class="btn outline" data-action="new-project" data-space="couple" data-template="trip">${I('plus',15)} Añadir un viaje (también pasado)</button></div>
 ${h.length?`<div class="bg-dests">${h.map(d=>`<section class="panel bg-dest"><h3>${I('pin',17)} ${e(d.destination)} <small>${d.stats.trips} ${d.stats.trips===1?'viaje':'viajes'}</small></h3><div class="bg-stats"><span><small>Total por viaje</small><b>${rng(d.stats.total)}</b></span><span><small>Alojamiento / noche</small><b>${rng(d.stats.stay_per_night)}</b></span><span><small>Comidas y salidas / día</small><b>${rng(d.stats.food_per_day)}</b></span><span><small>Billetes</small><b>${rng(d.stats.tickets)}</b></span>${d.stats.lead_stay?`<span><small>Reservasteis con</small><b>${d.stats.lead_stay.min}–${d.stats.lead_stay.max} días</b></span>`:''}</div>
  ${notesHtml(d.destination)}<div class="bg-trips">${d.trips.map(t=>`<button class="bg-trip" data-project="${t.id}"><span><b>${e(t.title)}</b><small>${short(t.start)} – ${short(t.end)} · ${t.nights} ${t.nights===1?'noche':'noches'}${t.lead_stay!=null?` · alojamiento reservado ${t.lead_stay} días antes`:''}</small></span><strong>${euro(t.total)}</strong></button>`).join('')}</div></section>`).join('')}</div>`:'<div class="full-empty">Todavía no hay viajes con fechas. Añadid uno (aunque sea pasado) y apuntad sus gastos con la fecha en que los comprasteis.</div>'}</div>`;}
function activityPage(){const f=S.actF||{user:'',space:'',project:'',type:''},all=(S.actData?.items||S.dash.recent||[]),items=all.filter(a=>!f.type||actType(a)===f.type),t=todayK(),y=addD(t,-1),wk=addD(t,-6);
 const users=S.dash?.users||[],projects=(S.dash?.projects||[]).filter(p=>!f.space||p.space===f.space),days={};for(const a of items){const k=new Date(a.created_at).toLocaleDateString('en-CA');(days[k]=days[k]||[]).push(a);}
 const dayName=k=>k===t?'Hoy':k===y?'Ayer':cap(new Date(k+'T12:00:00').toLocaleDateString('es-ES',{weekday:'long',day:'numeric',month:'long'}));
 const per=users.map((u,i)=>[u,all.filter(a=>a.user_id===u.id&&new Date(a.created_at).toLocaleDateString('en-CA')>=wk).length,i]),maxPer=Math.max(1,...per.map(x=>x[1])),typeCount=ACT_TYPES.map(([k,l,ic])=>[k,l,ic,all.filter(a=>actType(a)===k).length]).filter(x=>x[3]);
 const sel=(k,label,opts)=>`<label class="act-f"><small>${label}</small><select data-act-filter="${k}"><option value="">Todos</option>${opts.map(([v,l])=>`<option value="${e(v)}" ${f[k]===v?'selected':''}>${e(l)}</option>`).join('')}</select></label>`;
 const row=a=>{const ty=ACT_TYPES.find(x=>x[0]===actType(a))||ACT_TYPES[8],ui=users.findIndex(u=>u.id===a.user_id);return `<button class="act-row" ${a.project_id?`data-project="${e(a.project_id)}"`:`data-nav="${actType(a)==='ideas'?'ideas':'activity'}"`}><span class="act-time">${new Date(a.created_at).toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit'})}</span><span class="act-dot t-${ty[0]}">${I(ty[2],15)}</span><span class="act-body"><span class="act-who">${avatar(a.author||'?',ui===0?'av-first':'av-second')}<b>${e(a.author||'Alguien')}</b> ${e(a.action)}</span>${a.detail?`<span class="act-what">${e(a.detail)}</span>`:''}<span class="act-where">${I(a.project_kind==='trip'||a.project_destination?'plane':'folder',12)} ${e(a.project_title||'General')} · ${a.space==='work'?'Trabajo':'Nuestro espacio'} · ${e(ty[1])}</span></span>${a.project_id?`<span class="act-go">${I('arrow',15)}</span>`:''}</button>`;};
 return `<div class="page act-page"><div class="page-heading"><span class="eyebrow">CADA PASO CUENTA</span><h1>La actividad de los dos<span class="title-dot">.</span></h1><p>Qué cambió, quién lo hizo, cuándo y dónde impacta. Pulsa cualquier línea para ir al contenido.</p></div>
 <div class="act-sum"><div class="panel act-k"><small>Hoy</small><b>${all.filter(a=>new Date(a.created_at).toLocaleDateString('en-CA')===t).length}</b><span>cambios</span></div><div class="panel act-k"><small>Últimos 7 días</small><b>${all.filter(a=>new Date(a.created_at).toLocaleDateString('en-CA')>=wk).length}</b><span>cambios</span></div><div class="panel act-k act-people"><small>Quién ha movido más esta semana</small>${per.map(([u,n,i])=>`<div class="act-bar">${avatar(u.name,i===0?'av-first':'av-second')}<span><i style="width:${Math.round(n/maxPer*100)}%"></i></span><b>${n}</b></div>`).join('')}</div><div class="panel act-k act-types"><small>Por tipo</small><div>${typeCount.map(([k,l,ic,n])=>`<button class="act-tchip t-${k} ${f.type===k?'on':''}" data-action="act-type" data-v="${k}">${I(ic,12)} ${e(l)} <b>${n}</b></button>`).join('')||'<span class="hint">—</span>'}</div></div></div>
 <div class="act-filters panel">${sel('user','Persona',users.map(u=>[u.id,u.name]))}${sel('space','Espacio',[['work','Trabajo'],['couple','Nuestro espacio']])}${sel('project','Proyecto',projects.map(p=>[p.id,p.title]))}${sel('type','Tipo',ACT_TYPES.map(([k,l])=>[k,l]))}${Object.values(f).some(Boolean)?`<button class="btn subtle" data-action="act-clear">${I('close',14)} Quitar filtros</button>`:''}</div>
 <div class="act-days">${Object.keys(days).length?Object.entries(days).map(([k,xs])=>`<section class="act-day"><h3><span>${e(dayName(k))}</span><small>${xs.length} ${xs.length===1?'cambio':'cambios'}</small></h3><div class="panel act-list">${xs.map(row).join('')}</div></section>`).join(''):'<div class="full-empty">No hay actividad con estos filtros.</div>'}</div>
 ${S.actData?.more?`<button class="btn outline act-more" data-action="act-more">Cargar más antiguo</button>`:''}</div>`;}
// ---- DUPLA 6 · Conexiones (inventario 0148-0183) ----
const CX_ICON={google_calendar:['calendar','#e8f0fe','#1a73e8'],google_drive:['folder','#e6f4ea','#188038'],figma:['layers','#fdeee9','#f24e1e'],canva:['image','#e7f6fb','#00a3c4'],github:['globe','#eef0f3','#24292f'],stitch:['spark','#f1eaff','#7c4ddb'],other:['link','#f3f4f7','#5b6478']};
const CX_SUB={google_calendar:'Calendario compartido',google_drive:'Guardar archivos',figma:'Diseño y mockups',canva:'Diseño gráfico',github:'Código y repositorios',stitch:'Diseño de interfaces',other:'Enlace a cualquier herramienta'};
const cxScopeLabel=r=>r.scope_type==='global'?'Global · todos los proyectos':r.scope_type==='space'?(r.scope_id==='work'?'Espacio Trabajo':'Espacio Nuestro espacio'):'Proyecto · '+(r.project_title||'—');
function cxSel(){const v=S.cxScope||'global';const [type,id='']=v.split(':');const p=type==='project'?S.dash.projects.find(x=>x.id===id):null;return {type,id,p,space:type==='space'?id:p?.space};}
// Estado visual (0153-0158): conectado / pendiente / requiere autorización / solo enlace.
function cxState(pv){const meta=S.cx?.providers?.[pv]||{};if(pv==='google_calendar'){const g=S.googleStatus||{};return g.connected?['ok','Conectado']:g.available?['auth','Requiere autorización']:['pending','Pendiente de configurar'];}
 if(pv==='figma'||pv==='canva'){const d=S.designStatus?.[pv]||{};if(d.connected)return ['ok','Conectado'];const links=(S.cx?.items||[]).some(r=>r.provider===pv&&r.url);return links?['link','Solo enlace']:d.available?['auth','Requiere autorización']:['pending','Pendiente · usa un enlace'];}
 return (S.cx?.items||[]).some(r=>r.provider===pv&&r.url)?['link','Solo enlace']:['pending','Sin enlaces todavía'];}
// ¿Está activa en la selección actual? Exacta (se puede apagar) o heredada de un ámbito mayor.
function cxActive(pv){const s=cxSel(),rows=(S.cx?.items||[]).filter(r=>r.provider===pv&&!r.url);if(!(S.cx?.items||[]).some(r=>r.provider===pv))return {legacy:true};
 const exact=rows.find(r=>s.type==='global'?r.scope_type==='global':r.scope_type===s.type&&r.scope_id===s.id);if(exact)return {exact};
 const inherited=(S.cx.items||[]).find(r=>r.provider===pv&&(r.scope_type==='global'||(r.scope_type==='space'&&r.scope_id===s.space&&s.type==='project')));return inherited?{inherited}:{};}
function cxCard(pv){const [ic,bg,fg]=CX_ICON[pv],meta=S.cx.providers[pv],[st,stLabel]=cxState(pv),a=cxActive(pv),on=Boolean(a.exact||a.inherited||a.legacy);
 const links=(S.cx.items||[]).filter(r=>r.provider===pv&&r.url);
 return `<article class="cx-card"><div class="cx-top"><span class="cx-ic" style="background:${bg};color:${fg}">${I(ic,20)}</span><span class="cx-name"><b>${e(meta.name)}</b><small class="cx-st ${st}">${stLabel}</small></span>${a.legacy?`<button class="cx-only" data-action="cx-toggle" data-provider="${pv}" title="Ahora funciona en todo. Pulsa para activarla solo en la selección actual.">Solo aquí</button>`:a.inherited?`<span class="cx-inh" title="Activa por ${e(cxScopeLabel(a.inherited))}">Heredada</span>`:`<button class="st-toggle ${on?'on':''}" role="switch" aria-checked="${on}" aria-label="${e(meta.name)} en la selección" data-action="cx-toggle" data-provider="${pv}"><i></i></button>`}</div><p class="cx-sub">${CX_SUB[pv]}${a.legacy?' · <b>funciona en todo</b>':''}</p>
 ${links.length?`<ul class="cx-links">${links.map(r=>`<li><a href="${e(r.url)}" target="_blank" rel="noopener noreferrer">${I('external',13)} ${e(r.label||new URL(r.url).hostname)}</a><small>${e(cxScopeLabel(r))}</small></li>`).join('')}</ul>`:''}
 <div class="cx-actions">${pv==='google_calendar'?(S.googleStatus?.connected?`<button class="text-btn" data-action="google-disconnect">Desconectar</button>`:`<button class="text-btn" data-action="google-start" ${S.googleStatus?.available?'':'disabled'}>Autorizar</button>`):(pv==='figma'||pv==='canva')&&S.designStatus?.[pv]?.available?(S.designStatus[pv].connected?`<button class="text-btn" data-action="design-disconnect" data-provider="${pv}">Desconectar</button>`:`<button class="text-btn" data-action="design-start" data-provider="${pv}">Autorizar</button>`):''}${pv!=='google_calendar'?`<button class="text-btn" data-action="cx-add" data-provider="${pv}">${I('plus',13)} Añadir enlace</button>`:''}</div></article>`;}
function connectionsPage(){const ps=S.dash.projects.filter(p=>!p.archived),s=cxSel(),items=S.cx?.items||[];if(!S.cx)return `<div class="page"><p class="hint">Cargando conexiones…</p></div>`;
 const opts=[['global','Global · todos los proyectos'],['space:work','Espacio · Trabajo'],['space:couple','Espacio · Nuestro espacio'],...ps.map(p=>['project:'+p.id,(p.space==='work'?'Trabajo · ':'Nuestro espacio · ')+p.title])];
 return `<div class="page cx-page"><div class="st-head"><span class="st-head-ic">${I('link',22)}</span><div><h1>Conexiones</h1><p>Conecta tus herramientas favoritas, solo donde hagan falta.</p></div></div>
 <section class="panel cx-scope"><label>${I('layers',16)} Ver y activar para<select data-cx-scope>${options(opts,S.cxScope||'global')}</select></label><p class="hint">${s.type==='global'?'Lo que actives aquí funciona en todos los proyectos.':s.type==='space'?'Lo que actives aquí funciona en todos los proyectos de este espacio.':'Lo que actives aquí solo afecta a este proyecto. Más privacidad y menos ruido.'}</p></section>
 <div class="cx-grid">${Object.keys(S.cx.providers).map(cxCard).join('')}<button class="cx-card cx-add" data-action="cx-add" data-provider="other">${I('plus',22)}<b>Añadir otra conexión</b><small>Cualquier herramienta con enlace</small></button></div>
 <section class="panel cx-perms"><h3>${I('lock',17)} Qué está activo, dónde y con qué permisos</h3>${items.length?`<div class="table-scroll"><table class="cx-table"><thead><tr><th>Integración</th><th>Dónde</th><th>Permisos</th><th>Enlace</th><th></th></tr></thead><tbody>${items.map(r=>`<tr><td><b>${e(S.cx.providers[r.provider]?.name||r.provider)}</b></td><td>${e(cxScopeLabel(r))}</td><td><select data-cx-perm="${r.id}" aria-label="Permisos">${options([['read','Solo ver'],['write','Ver y editar']],r.permission)}</select></td><td>${r.url?`<a href="${e(r.url)}" target="_blank" rel="noopener noreferrer">${e(r.label||'Abrir')}</a>`:'—'}</td><td><button class="icon-btn" data-action="cx-remove" data-id="${r.id}" aria-label="Quitar">${I('trash',15)}</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="hint">Todavía no hay restricciones: las integraciones que ya funcionaban siguen activas en todo. En cuanto actives una en un proyecto, solo funcionará donde la actives.</p>'}</section>
 <details class="panel cx-legacy"><summary>${I('settings',16)} Importaciones, automatizaciones e IA (funciones actuales)</summary>${legacyConnections()}</details></div>`;}
function legacyConnections(...a){const m=lazyMod('conexiones',()=>({S,$,e,I,fmt}));return m?m.legacyConnections(...a):'<p class="muted lazy-wait">Cargando…</p>';}
