const PREF_DEFAULTS={theme:'light',accent:'indigo',notify_types:['events','tasks','projects','comments','trip_reminders','budget','ideas'],reminder_lead:'day_before',calendar_view:'month',week_start:'monday',pdf_cover:true,pdf_expenses:true,pdf_notes:true,pdf_activity:false,default_color_work:'indigo',default_color_couple:'rose',home_show_work:true,home_show_couple:true,agent_scope:'all',daily_summary:true,daily_calendar:true,agent_alerts:true};
const pref=k=>S.prefs?.[k]??PREF_DEFAULTS[k];
const ACCENTS={indigo:['#3d5bd9','#2f49c0','#eaefff'],violet:['#7c4ddb','#6638c4','#f1eaff'],sky:['#1f8fe0','#1373bb','#e4f4ff'],emerald:['#1f9d6b','#167a52','#e2f6ec'],coral:['#e2566a','#c63f53','#ffe9ec'],amber:['#d08a0b','#a86d03','#fff4dc']};
// Aplica tema y color en toda la app; «sistema» sigue al móvil/ordenador en tiempo real.
function applyTheme(){const root=document.documentElement,t=pref('theme'),dark=t==='dark'||(t==='system'&&Boolean(globalThis.matchMedia?.('(prefers-color-scheme: dark)')?.matches));root.dataset.theme=dark?'dark':'light';const [a,a2,soft]=ACCENTS[pref('accent')]||ACCENTS.indigo;root.style.setProperty('--v6-accent',a);root.style.setProperty('--v6-accent-2',a2);root.style.setProperty('--v6-accent-soft',dark?'rgba(255,255,255,.08)':soft);document.querySelector('meta[name=theme-color]')?.setAttribute('content',dark?'#0d1322':'#141c31');}
globalThis.matchMedia?.('(prefers-color-scheme: dark)')?.addEventListener?.('change',()=>{if(pref('theme')==='system')applyTheme();});
async function savePref(key,value){const prev=S.prefs?.[key];S.prefs={...(S.prefs||{}),[key]:value};applyTheme();render();try{await api('/api/prefs','PUT',{[key]:value});}catch(ex){S.prefs={...S.prefs,[key]:prev};applyTheme();render();toast(ex.message,'error');}}
const toggle=(key,label,hint='')=>{const on=Boolean(pref(key));return `<div class="st-row"><span><b>${label}</b>${hint?`<small>${hint}</small>`:''}</span><button class="st-toggle ${on?'on':''}" role="switch" aria-checked="${on}" aria-label="${e(label)}" data-action="pref-toggle" data-key="${key}"><i></i></button></div>`;};
const segmented=(key,label,items,hint='')=>`<div class="st-row"><span><b>${label}</b>${hint?`<small>${hint}</small>`:''}</span><div class="st-seg" role="group" aria-label="${e(label)}">${items.map(([v,l,ic])=>`<button class="${pref(key)===v?'active':''}" aria-pressed="${pref(key)===v}" data-action="pref-set" data-key="${key}" data-value="${v}">${ic?I(ic,14)+' ':''}${l}</button>`).join('')}</div></div>`;
const swatches=(key,label,list)=>`<div class="st-row"><span><b>${label}</b></span><div class="st-swatches">${list.map(c=>`<button class="sw sw-${c} ${pref(key)===c?'active':''}" aria-label="${c}" aria-pressed="${pref(key)===c}" data-action="pref-set" data-key="${key}" data-value="${c}"></button>`).join('')}</div></div>`;
const NOTIFY_LABELS={events:['Eventos y planes','Nuevos planes y cambios de fecha'],tasks:['Tareas','Asignadas, completadas o que vencen'],projects:['Cambios de proyecto','Estado, descripción, archivos'],comments:['Comentarios','Cuando la otra persona escribe'],trip_reminders:['Recordatorios de viaje','Antes de salir y cada día del viaje'],budget:['Presupuestos','Gastos nuevos o que superan lo previsto'],ideas:['Ideas guardadas','Ideas nuevas en el buzón']};
