function settingsTab(...a){const m=lazyMod('ajustes',()=>({S,$,avatar,e,I,segmented,swatches,ACCENTS,pref,toggle,NOTIFY_LABELS,fmt,api,duplaAvatar}));return m?m.settingsTab(...a):'<p class="muted lazy-wait">Cargando…</p>';}
function settingsPage(){const t=S.settingsTab||'cuenta';return `<div class="page st-page"><div class="st-head"><span class="st-head-ic">${I('settings',22)}</span><div><h1>Ajustes</h1><p>Vuestra información pertenece a los dos.</p></div></div><nav class="st-tabs" role="tablist" aria-label="Secciones de ajustes">${SETTINGS_TABS.map(([id,l,ic])=>`<button role="tab" aria-selected="${t===id}" class="${t===id?'active':''}" data-action="settings-tab" data-tab-id="${id}">${I(ic,15)} ${l}</button>`).join('')}</nav><div class="st-body">${settingsTab()}</div></div>`;}

