   body=`${fld('Tarea','title',x.title||'','text','maxlength="200" required placeholder="Pedir cita, comprar regalo…"')}${area('Detalles','notes',x.notes||'',2,'maxlength="3000"')}<div class="form-two">${sel('Para quién','assignee',[...users.map(u=>[u.id,u.name]),['','Los dos']],x.assignee||'')}${sel('Prioridad','priority',Object.entries(BD_PRIO),x.priority||'normal')}</div><div class="form-two">${sel('Estado','status',BD_COLS,x.status||'todo')}${fld('Fecha límite','due_date',x.due_date||'','date')}</div>${sel('Depende de (tarea padre)','parent_id',[['','— Ninguna —'],...others.map(y=>[y.id,y.title]),...(x.parent_id&&!others.some(y=>y.id===x.parent_id)?[[x.parent_id,((S.board||[]).find(y=>y.id===x.parent_id)||{}).title||'Tarea']]:[])],x.parent_id||'')}<p class="hint">Si tiene tarea padre, no se podrá terminar hasta que la padre esté terminada.</p>${x.id?taskNotesBox('board',x.id):''}`;
